      "id": "modern-c04-l17-p01-019",
      "title": "パリ講和会議への期待",
      "body": [
        "第一次世界大戦で中国は<strong class=\"source-bold\">連合国側で参戦</strong>したから、戦勝国として<strong class=\"source-bold\">パリ<ruby>講和<rt>こうわ</rt></ruby>会議に出席</strong>できる。この時、中国の人びとは「ウィルソンの十四カ条で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">民族<ruby>自決<rt>じけつ</rt></ruby></strong></span>って言ってるから、中国の主張も聞いてもらえるはず」って期待していた。"
      ],
      "plainBody": [
        "第一次世界大戦で中国は連合国側で参戦したから、戦勝国としてパリ講和会議に出席できる。この時、中国の人びとは「ウィルソンの十四カ条で民族自決って言ってるから、中国の主張も聞いてもらえるはず」って期待していた。"
      ],
