      "title": "中国代表団の調印拒否と政府への影響",
      "body": [
        "このため、パリにいた中国代表団は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴェルサイユ条約の調印を拒否</strong></span>し、政権に就いていた<strong class=\"source-bold\"><ruby>段祺瑞<rt>だんきずい</rt></ruby></strong>も、調印拒否を認めるしかなくなったんだ。これ、<strong class=\"source-bold\">大衆運動が政府を動かした</strong>瞬間だよ。"
      ],
