      "id": "modern-c04-l17-p01-028",
      "title": "同化政策と朝鮮文化",
      "body": [
        "これは、日本の内地と朝鮮半島の制度の違いを小さくして、というか、要するに<strong class=\"source-bold\">朝鮮半島を日本と同じにしよう</strong>って同化政策なんだけど、結果的には<strong class=\"source-bold\">日本語教育や神社<ruby>参拝<rt>さんぱい</rt></ruby></strong>などの強制になってしまい、朝鮮文化を消すことになっちゃったんだ。"
      ],
      "plainBody": [
        "これは、日本の内地と朝鮮半島の制度の違いを小さくして、というか、要するに朝鮮半島を日本と同じにしようって同化政策なんだけど、結果的には日本語教育や神社参拝などの強制になってしまい、朝鮮文化を消すことになっちゃったんだ。"
      ],
