      "title": "中国国民党への改組と国民革命",
      "body": [
        "そこで、秘密結社だった<strong class=\"source-bold\">中華革命党</strong>を<strong class=\"source-bold\">全国民に開かれた大衆政党</strong>である<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中国国民党</strong></span>に変え、民衆も巻き込んだ<strong class=\"source-bold\">国民革命</strong>を進めることにしたんだ。"
      ],
