      "body": [
        "五・三〇運動で強くなった<strong class=\"source-bold\">共産党を警戒する右派</strong>は蔣介石と組み、<strong class=\"source-bold\">共産党と一緒に民衆運動を進めようとする左派</strong>と対立し始めたけど、軍の指揮権を握る<strong class=\"source-bold\">蔣介石を中心</strong>に、1926年7月<strong class=\"source-bold\">北伐（第1次北伐）</strong>が始まった。こんな状態で本当に勝てるのかな。"
      ],
