      "body": [
        "この主導権争いで、最初に手を打ったのは左派だよ。1927年、<strong class=\"source-bold\">国民党左派と共産党</strong>は<ruby>広州<rt>こうしゅう</rt></ruby>にあった<strong class=\"source-bold\">国民政府を<ruby>武漢<rt>ぶかん</rt></ruby>に<ruby>遷都<rt>せんと</rt></ruby></strong>して（<strong class=\"source-bold\">武漢政府</strong>）、<strong class=\"source-bold\"><ruby>汪兆銘<rt>おうちょうめい</rt></ruby></strong>を最高指導者として蔣介石から権力を奪おうとした。"
      ],
