      "body": [
        "<strong class=\"source-bold\"><ruby>列強<rt>れっきょう</rt></ruby></strong>や<strong class=\"source-bold\"><ruby>浙<rt>せっ</rt></ruby><ruby>江財閥<rt>こうざいばつ</rt></ruby></strong>と手を組んだ蔣介石軍は<strong class=\"source-bold\">共産党員を徹底的に取り締まり</strong>、武器を取り上げ、反発する者は虐殺した！。こうして<strong class=\"source-bold\">第1次国共合作は崩壊</strong>したよ。"
      ],
