      "id": "modern-c04-l17-p02-043",
      "title": "武漢政府の合流と国民党のみの政府",
      "body": [
        "武漢政府の<strong class=\"source-bold\">国民党左派</strong>は蔣介石に対抗しようとしたんだけど、最終的には共産党と手を切って<strong class=\"source-bold\">南京政府に合流</strong>するしかなかった。こうして、<strong class=\"source-bold\">国民党のみになった南京国民政府</strong>では、<strong class=\"source-bold\">蔣介石が主導権</strong>を握ったんだよ。"
      ],
      "plainBody": [
        "武漢政府の国民党左派は蔣介石に対抗しようとしたんだけど、最終的には共産党と手を切って南京政府に合流するしかなかった。こうして、国民党のみになった南京国民政府では、蔣介石が主導権を握ったんだよ。"
      ],
