      "id": "modern-c04-l17-p02-045",
      "title": "張作霖と日本の満洲進出",
      "body": [
        "　北京政府の実権を握る<strong class=\"source-bold\"><ruby>奉天軍閥<rt>ほうてんぐんばつ</rt></ruby></strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>張作霖<rt>ちょうさくりん</rt></ruby></strong></span>は<strong class=\"source-bold\">日本軍の支援</strong>を受けていたんだけど、<strong class=\"source-bold\">日本も張作霖を利用して<ruby>満洲<rt>まんしゅう</rt></ruby>に進出</strong>していたから、蔣介石軍が北京にくると<ruby>厄介<rt>やっかい</rt></ruby>だ。"
      ],
