      "id": "modern-c04-l17-p02-052",
      "title": "満洲の張学良の帰順と北伐完成",
      "body": [
        "そりゃ、自分の本拠地だった満洲を取られ、親父を爆殺されたんだもん、日本に協力する理由は全くない。こうして、満洲（<strong class=\"source-bold\"><ruby>東三省<rt>とうさんしょう</rt></ruby></strong>）を支配する<strong class=\"source-bold\">張学良が国民党に<ruby>帰順<rt>きじゅん</rt></ruby></strong>し、ひとまず<strong class=\"source-bold\">南京国民政府による中国統一</strong>が完成したんだ（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">北伐完成</strong></span>）。"
      ],
