      "id": "modern-c04-l17-p03-001",
      "title": "日本の好景気と戦後の相次ぐ不況",
      "body": [
        "日本は、第一次世界大戦の時に輸出が拡大して、むちゃくちゃ経済が発展したんだけど、戦後は輸出が減って<strong class=\"source-bold\">戦後<ruby>恐慌<rt>きょうこう</rt></ruby></strong>が起こり、1923年には追い打ちをかけるように<strong class=\"source-bold\">関東大震災</strong>が起き、1927年には<strong class=\"source-bold\">金融恐慌</strong>も発生した。しかも1929年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">世界恐慌</strong></span>の影響も受けて、日本は<ruby>不況<rt>ふきょう</rt></ruby>のどん底におちいった。"
      ],
      "plainBody": [
        "日本は、第一次世界大戦の時に輸出が拡大して、むちゃくちゃ経済が発展したんだけど、戦後は輸出が減って戦後恐慌が起こり、1923年には追い打ちをかけるように関東大震災が起き、1927年には金融恐慌も発生した。しかも1929年には世界恐慌の影響も受けて、日本は不況のどん底におちいった。"
      ],
