      "body": [
        "根拠地を維持できなくなった共産党は<strong class=\"source-bold\"><ruby>瑞金<rt>ずいきん</rt></ruby>から撤退</strong>することを決め、蔣介石の攻撃から逃げるために、西へと移動を始めたんだ。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">長征</strong></span>の始まりだよ。"
      ],
      "plainBody": [
        "根拠地を維持できなくなった共産党は瑞金から撤退することを決め、蔣介石の攻撃から逃げるために、西へと移動を始めたんだ。これが長征の始まりだよ。"
      ],
