      "body": [
        "そして、<strong class=\"source-bold\"><ruby>八<rt>はち</rt></ruby>・<ruby>一<rt>いち</rt></ruby>宣言に共感</strong>したのが、自分の本拠地を日本に奪われた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>張学良<rt>ちょうがくりょう</rt></ruby></strong></span>だ。張学良は日本から<ruby>満洲<rt>まんしゅう</rt></ruby>を取り返したいから、共産党と内戦なんかをやってる場合じゃない。"
      ],
