      "body": [
        "これに対し、<strong class=\"source-bold\">蔣介石</strong>は戦争が<strong class=\"source-bold\">長期戦になると判断</strong>して、兵力を温存するために、国民政府の首都をいったん<strong class=\"source-bold\"><ruby>武漢<rt>ぶかん</rt></ruby></strong>、さらに内陸の<strong class=\"source-bold\"><ruby>四川<rt>しせん</rt></ruby>省</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>重慶<rt>じゅうけい</rt></ruby></strong></span>に移すことを決めたんだけど、この時、中国軍は南京からの撤退に失敗して多数の犠牲者を出した。"
      ],
