      "title": "鉄道と都市の占領と農村のゲリラ戦",
      "body": [
        "ただ、日本は<ruby>華北<rt>かほく</rt></ruby>から<ruby>江南<rt>こうなん</rt></ruby>へと、<strong class=\"source-bold\">鉄道に沿って都市を占領</strong>するだけだった。ていうか、あれだけ広い<strong class=\"source-bold\">中国の農村部まで占領するのはムリ</strong>だよ。中国では共産党が農村部に根拠地（<strong class=\"source-bold\">解放区</strong>）をつくって<strong class=\"source-bold\">ゲリラ戦</strong>で対抗し、日本軍はあっという間に行き詰った。"
      ],
      "plainBody": [
        "ただ、日本は華北から江南へと、鉄道に沿って都市を占領するだけだった。ていうか、あれだけ広い中国の農村部まで占領するのはムリだよ。中国では共産党が農村部に根拠地（解放区）をつくってゲリラ戦で対抗し、日本軍はあっという間に行き詰った。"
      ],
