      "id": "modern-c04-l17-p04-020",
      "title": "日米通商航海条約の破棄と輸出制限",
      "body": [
        "日本がどんどん戦線を拡大するのを見て、ついに<strong class=\"source-bold\">アメリカ</strong>が動き出したよ。さっきも話したけど、アメリカには<strong class=\"source-bold\">交戦国に戦略物資を輸出しちゃいけない</strong>っていう<strong class=\"source-bold\">中立法</strong>がある。アメリカは日本に対して「日本は交戦国だから、戦略物資は輸出してやらない」と言って<strong class=\"source-bold\">日米通商航海条約を<ruby>破棄<rt>はき</rt></ruby></strong>し、<strong class=\"source-bold\">石油・くず鉄の輸出制限</strong>を決めたんだ。"
      ],
      "plainBody": [
        "日本がどんどん戦線を拡大するのを見て、ついにアメリカが動き出したよ。さっきも話したけど、アメリカには交戦国に戦略物資を輸出しちゃいけないっていう中立法がある。アメリカは日本に対して「日本は交戦国だから、戦略物資は輸出してやらない」と言って日米通商航海条約を破棄し、石油・くず鉄の輸出制限を決めたんだ。"
      ],
