      "body": [
        "この時日本では「バスに乗り遅れるな！」って主張があった。これは、ドイツが戦争に勝つ「バス」に乗ってるから、乗り遅れずに、一気に東南アジアを取れ！ってことだ。だって、<strong class=\"source-bold\">インドシナ（ベトナム）はフランス領、インドネシアはオランダ領</strong>だから、どっちも<strong class=\"source-bold\">本国がドイツに降伏</strong>してるでしょ。今なら一気に勝てる！"
      ],
