      "id": "modern-c04-l17-p04-025",
      "title": "北部仏印進駐と二つの目的",
      "body": [
        "　こうして日本は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フランス領インドシナ北部</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">北部仏印</strong></span>】</strong>に軍を進めたよ。これには、<strong class=\"source-bold\">南進政策の拠点</strong>をつくること、さらに<ruby>重慶<rt>じゅうけい</rt></ruby>の<ruby>蔣介石<rt>しょうかいせき</rt></ruby>に支援物資を送る「<strong class=\"source-bold\"><ruby>援蔣<rt>えんしょう</rt></ruby>ルート</strong>」<strong class=\"source-bold\">を<ruby>遮断<rt>しゃだん</rt></ruby></strong>すること、っていう2つの目的があるよ。"
      ],
      "plainBody": [
        "　こうして日本はフランス領インドシナ北部 【北部仏印】に軍を進めたよ。これには、南進政策の拠点をつくること、さらに重慶の蔣介石に支援物資を送る「援蔣ルート」を遮断すること、っていう2つの目的があるよ。"
      ],
