export const sourcePages = {
  "310": "<h2>310</h2>\n<h1><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第17回</strong></span> <span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">戦間期の東アジア</strong></span></h1>\n<p>今回は戦間期のアジアの2回目、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">中国を中心とする東アジア世界</strong></u>だよ。<ruby>辛亥<rt>しんがい</rt></ruby>革命のあとの中国は、一体どうなっていくんだろう？</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">大きくつかもう！</span></h3>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">新文化運動と五・四運動</strong></span> <span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">311〜312ページ</span></p>\n<p><span data-source-marker=\"outline-arrow\" data-source-color=\"red\" style=\"color:#e52715\">⇩</span></p>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">孫文の国民革命と北伐</strong></span> <span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">312〜318ページ</span></p>\n<p><span data-source-marker=\"outline-arrow\" data-source-color=\"red\" style=\"color:#e52715\">⇩</span></p>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">日本の侵略と国共内戦</strong></span> <span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">318〜322ページ</span></p>\n<p><span data-source-marker=\"outline-arrow\" data-source-color=\"red\" style=\"color:#e52715\">⇩</span></p>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">4</span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">日中戦争</strong></span> <span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">322〜325ページ</span></p>\n<blockquote><p>国民党・共産党、そして日本。3つの勢力の関係が、今回のポイントだよ！</p></blockquote>\n<p>辛亥革命で<ruby>清<rt>シン</rt></ruby>朝が滅亡したものの、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\"><ruby>袁世凱<rt>えんせいがい</rt></ruby>の<ruby>独裁<rt>どくさい</rt></ruby></strong></u>、そして<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\"><ruby>軍閥<rt>ぐんばつ</rt></ruby>政権</strong></u>になってしまった中国では、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\"><ruby>孫文<rt>そんぶん</rt></ruby></strong></u>がもう一度革命運動を立て直していくよ。そして、いよいよ<ruby>北伐<rt>ほくばつ</rt></ruby>に向かおう！ってところで<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">孫文が死去</strong></u>！。後継者となった<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\"><ruby>蔣介石<rt>しょうかいせき</rt></ruby></strong></u>が国民革命を続けるんだけど……<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">共産党との対立</strong></u>が始まるんだ。蔣介石の<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">国民党</strong></u>、<ruby>毛沢東<rt>もうたくとう</rt></ruby>の<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">共産党</strong></u>が対立するなかで、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">中国進出を進める日本</strong></u>も大きな影響を与えることになるよ。この3つの勢力はどんなふうにかかわっていくんだろう？　そして、第二次世界大戦が始まる前に、東アジアでは早くも<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">日中戦争</strong></u>が始まってしまうんだ。</p>\n<p>それじゃあ、じっくり見ていこう。戦間期の東アジアの始まり〜。</p>",
  "311": "<h2>311</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">新文化運動と五・四運動</u></p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">新文化運動と五・四運動</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">「中国人の意識を根本的に変えよう！」。新文化運動が始まった</strong></span></h4>\n<p>辛亥革命のあと、中国は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">袁世凱</strong></span>の独裁になったから、清が滅んだだけで、政治も社会もほとんど何も変わらなかったよね。しかも<strong class=\"source-bold\">袁世凱の死後</strong>は各地の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">軍閥</strong></span>が政権を争う混乱の時代になった。一方で、第一次世界大戦中の東アジアの好景気で、中国でも<strong class=\"source-bold\">軽工業を中心に中国企業が成長</strong>した。反面、<strong class=\"source-bold\">都市労働者の増加</strong>で社会問題も起きていた。こうした事態を見て、中国の知識人たちが始めたのが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">新文化運動</strong></span>だ。</p>\n<p><strong class=\"source-bold\">新文化運動</strong>とは、ヨーロッパの近代思想に触れた知識人たちが、「本当に近代化をするためには、<strong class=\"source-bold\">中国人の意識を根本的に変えなきゃいけない</strong>」って思って始めた運動だよ。皇帝の専制政治が続いていた中国の人びとには、とりあえず「エラい人の言うことを聞いておけ」っていう意識が染みついていたからね。</p>\n<p>そこで、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>陳独秀<rt>ちんどくしゅう</rt></ruby></strong></span>は中国の青年たちに対し「もっと<strong class=\"source-bold\">自主的</strong>に、もっと<strong class=\"source-bold\">国際的</strong>にならなきゃいけない！」って訴え、雑誌『<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>新青年<rt>しんせいねん</rt></ruby></strong></span>』（創刊した時の名前は『<strong class=\"source-bold\">青年雑誌</strong>』だよ）を創刊し、「<strong class=\"source-bold\">民主と科学</strong>」をスローガンに<strong class=\"source-bold\">欧米の近代思想を紹介</strong>した。若者はこの雑誌に飛びついて、新しい思想に感動したんだ。この雑誌のなかで、アメリカに留学した<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>胡適<rt>こてき</rt></ruby></strong></span>は、わかりやすい<strong class=\"source-bold\">口語体（話し言葉）</strong>で現在の中国の問題点を浮き彫りにするような<strong class=\"source-bold\">文学</strong>（小説とかだね）をつくろう！っていう<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>白話<rt>はくわ</rt></ruby></strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">口語</strong></span>】</strong> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">文学</strong></span>を提唱した。だって、一般の人たちに難しい論文を見せたって「訳わかんないこと言ってんなー」って言われちゃうでしょ？　だったら<strong class=\"source-bold\">小説にすればいい</strong>。これを受けて<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>魯迅<rt>ろじん</rt></ruby></strong></span>は、『<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>狂人日記<rt>きょうじんにっき</rt></ruby></strong></span>』（これが<strong class=\"source-bold\">初めて口語で書かれた文学</strong>だよ）や『<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>阿Ｑ正伝<rt>あきゅうせいでん</rt></ruby></strong></span>』を著した。特に『阿Ｑ正伝』では、<strong class=\"source-bold\">貧農を主人公</strong>に、旧体制下で現実を見ない民衆の意識（<strong class=\"source-bold\"><ruby>奴隷<rt>どれい</rt></ruby>根性</strong>やら<strong class=\"source-bold\">中華思想</strong>だね）を徹底的に批判したんだ。こうした文学での動きは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">文学革命</strong></span>と呼ばれている。</p>\n<blockquote><p>『阿Ｑ正伝』を読んでると阿Ｑにムカつくの。てか、阿Ｑを通して「中国人の意識なんてこんなものですよ」って言いたかったんだ</p></blockquote>\n<p>さらに<strong class=\"source-bold\">第一次世界大戦終結</strong>のニュースが伝わってくると「民主が皇帝に勝った！」って盛りあがり、<strong class=\"source-bold\"><ruby>北京<rt>ペキン</rt></ruby>大学</strong>では学生や教員の集会も開かれた。さらに、<strong class=\"source-bold\">ロシア革命の影響</strong>を受けた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>李大釗<rt>りたいしょう</rt></ruby></strong></span>が中国に<strong class=\"source-bold\">マルクス主義を紹介</strong>すると、<strong class=\"source-bold\">知識人たちは社会主義に傾いた</strong>よ。そして、一般の民衆の意識にも少しずつ変化が現れたんだ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ヴェルサイユ条約への抗議から民衆が爆発。<ruby>五<rt>ご</rt></ruby>・<ruby>四<rt>し</rt></ruby>運動が起きた！</strong></span></h4>\n<p>第一次世界大戦で中国は<strong class=\"source-bold\">連合国側で参戦</strong>したから、戦勝国として<strong class=\"source-bold\">パリ<ruby>講和<rt>こうわ</rt></ruby>会議に出席</strong>できる。この時、中国の人びとは「ウィルソンの十四カ条で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">民族<ruby>自決<rt>じけつ</rt></ruby></strong></span>って言ってるから、中国の主張も聞いてもらえるはず」って期待していた。でも会議が</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "312": "<h2>312</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第17回</strong></span> 戦間期の東アジア</p>\n<p>始まってみると、<strong class=\"source-bold\">ヨーロッパ各国はアジアのことに興味なし</strong>。だって、ドイツの弱体化のことしか考えてないからね。中国が要求した<strong class=\"source-bold\">日本の二十一カ条要求の<ruby>破棄<rt>はき</rt></ruby>、<ruby>山東<rt>さんとう</rt></ruby>半島の返還</strong>などは<strong class=\"source-bold\">すべて拒否</strong>されたんだ。</p>\n<p>これに対して、数千人の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>北京<rt>ペキン</rt></ruby>大学</strong></span>の学生が「ヴェルサイユ条約調印反対！」と怒って、<ruby>天安門<rt>てんあんもん</rt></ruby>の前で抗議集会を開いた。さらに、北京にある各国の大使館に抗議文を提出したり、外交の責任者の家を襲うような事件も起きて、各地に<strong class=\"source-bold\">ヴェルサイユ条約調印反対、反日、反帝国主義、反封建主義</strong>のデモが広がったよ。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>五<rt>ご</rt></ruby>・<ruby>四<rt>し</rt></ruby>運動</strong></span>だ。このため、パリにいた中国代表団は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴェルサイユ条約の調印を拒否</strong></span>し、政権に就いていた<strong class=\"source-bold\"><ruby>段祺瑞<rt>だんきずい</rt></ruby></strong>も、調印拒否を認めるしかなくなったんだ。これ、<strong class=\"source-bold\">大衆運動が政府を動かした</strong>瞬間だよ。その後、<strong class=\"source-bold\">ワシントン会議での九カ国条約</strong>で中国の主権尊重と領土保全が再度確認されると、<strong class=\"source-bold\">日中間の交渉で山東半島の旧ドイツ利権は中国に返還</strong>されたんだ。</p>\n<blockquote><p>五・四運動は「大衆運動が政府を動かした瞬間」だよ！　これが、中国の民族運動に大きな影響を与えるんだ</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">朝鮮でも、民族<ruby>自決<rt>じけつ</rt></ruby>の影響で<ruby>三<rt>さん</rt></ruby>・<ruby>一<rt>いち</rt></ruby>独立運動が起きた！</strong></span></h4>\n<p>中国で五・四運動が起きたのと同じ1919年、<strong class=\"source-bold\">日本の<ruby>統治<rt>とうち</rt></ruby>下にあった朝鮮</strong>でも、パリ<ruby>講和<rt>こうわ</rt></ruby>会議で唱えられた「<strong class=\"source-bold\">民族自決</strong>」の影響で独立の要求が高まったよ。そして3月1日には、京城（ソウル）で「<strong class=\"source-bold\">朝鮮独立<ruby>万歳<rt>ばんざい</rt></ruby>！</strong>」と叫ぶ民衆のデモが起こり、朝鮮全土に広がったんだ。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">三・一独立運動</strong></span>だよ。この時、日本は<strong class=\"source-bold\">軍と警察を動員してデモを<ruby>鎮圧<rt>ちんあつ</rt></ruby></strong>したんだけど、かなりショックを受けた。そして三・一独立運動後には、<ruby>武断<rt>ぶだん</rt></ruby>政治をゆるめて<strong class=\"source-bold\">文化政治</strong>に転換したよ。これは、日本の内地と朝鮮半島の制度の違いを小さくして、というか、要するに<strong class=\"source-bold\">朝鮮半島を日本と同じにしよう</strong>って同化政策なんだけど、結果的には<strong class=\"source-bold\">日本語教育や神社<ruby>参拝<rt>さんぱい</rt></ruby></strong>などの強制になってしまい、朝鮮文化を消すことになっちゃったんだ。</p>\n<p>また、朝鮮の民族運動家たちは、三・一独立運動で盛り上がった独立運動をなんとか続けようと、<ruby>上海<rt>シャンハイ</rt></ruby>で<strong class=\"source-bold\">大韓民国臨時政府</strong>をつくったよ。ただ、<ruby>列強<rt>れっきょう</rt></ruby>に頼りきりだったから、すぐに実体を失っちゃった。ちなみに、この時初代大統領とされた<strong class=\"source-bold\"><ruby>李承晩<rt>りしょうばん</rt></ruby></strong>は、第二次世界大戦後に<strong class=\"source-bold\">大韓民国が独立した時の初代大統領</strong>だよ。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">孫文の国民革命と北伐</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">大衆運動に発展した五・四運動が、中国の民族運動を変えた！</strong></span></h4>\n<p>それじゃあ中国に戻るよ。<strong class=\"source-bold\">大衆運動が政府を動かした五・四運動</strong>に<ruby>衝撃<rt>しょうげき</rt></ruby>を受けて、考え方を変えたのが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>孫文<rt>そんぶん</rt></ruby></strong></span>だ。孫文は、今までの自分の革命運動が不十分だったことを思い知った。だって、これまでは<strong class=\"source-bold\">知識人とか金持ち</strong>ばかりを相手にし</p>",
  "313": "<h2>313</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">孫文の国民革命と北伐</u></p>\n<p>て、<strong class=\"source-bold\">民衆には全く目を向けなかった</strong>からね。そこで、秘密結社だった<strong class=\"source-bold\">中華革命党</strong>を<strong class=\"source-bold\">全国民に開かれた大衆政党</strong>である<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中国国民党</strong></span>に変え、民衆も巻き込んだ<strong class=\"source-bold\">国民革命</strong>を進めることにしたんだ。目標は、<strong class=\"source-bold\">北洋軍閥</strong>（<ruby>袁世凱<rt>えんせいがい</rt></ruby>の流れをくむ<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>軍閥<rt>ぐんばつ</rt></ruby></strong></span>）が主導権を握る<strong class=\"source-bold\">北京政府</strong>の打倒（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>北伐<rt>ほくばつ</rt></ruby></strong></span>）。ただ、国民党はまだ大きくなかったから、孫文は<strong class=\"source-bold\">南部の軍閥と組んで<ruby>広東<rt>カントン</rt></ruby>軍政府</strong>をつくり北京政府に対抗したんだけど、権力闘争がひどくて安定した勢力にはならなかったんだ。</p>\n<p>一方で、五・四運動に感動したのは孫文だけじゃなかった。もう一つが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">コミンテルン</strong></span>だよ。<strong class=\"source-bold\">ロシア革命</strong>のあと、<strong class=\"source-bold\">レーニン</strong>を中心とするソヴィエト＝ロシアは<strong class=\"source-bold\">世界革命を目指してコミンテルンを結成</strong>し、ヨーロッパでいくつか革命を起こしたけど、全部挫折しちゃった。そしたら中国で大衆運動がもり上がってるから、「中国なら革命が成功するかもしれない！」と思って、中国への接近を始めたんだ。</p>\n<blockquote><p>五・四運動で中国の大衆運動の力を知った孫文とコミンテルンが、いよいよ接近し始めるよ</p></blockquote>\n<p>ただ、これまでの<strong class=\"source-bold\">ロシア帝国</strong>はさんざん<strong class=\"source-bold\">中国を<ruby>侵略<rt>しんりゃく</rt></ruby></strong>してきたから、中国人はロシアを信用していない。そこでソヴィエト＝ロシア（のちのソ連）は「これまでのロシア帝国とは違う」っていうのを中国人に見せるため、外務人民委員代理のカラハンが、<strong class=\"source-bold\">帝政ロシア時代に獲得した利権や不平等条約を無償（タダ）で<ruby>破棄<rt>はき</rt></ruby></strong>するって宣言したよ。これが<strong class=\"source-bold\">カラハン宣言</strong>だ。これには中国の人たちも感動。だって、これまで利権を破棄してくれる国はなかったからね。まあ、あとから「<strong class=\"source-bold\"><ruby>東清<rt>とうしん</rt></ruby>鉄道は除外</strong>で」なんて言ってきたのは、やっぱりロシアだけど。</p>\n<p>そして、<strong class=\"source-bold\">コミンテルンの指導</strong>のもと、上海で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中国共産党</strong></span>が結成されたよ。初代委員長は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>陳独秀<rt>ちんどくしゅう</rt></ruby></strong></span>だ。まだ<strong class=\"source-bold\"><ruby>毛沢東<rt>もうたくとう</rt></ruby>じゃない</strong>からね。ついつい「中国共産党＝毛沢東」ってイメージになっちゃうから気をつけよう。それに、この時点での共産党員はわずか50名程度だから、革命を起こすっていうのは、ちょっとムリがあるよね。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">合</strong></span><span data-source-color=\"white\" data-source-background=\"brown\" style=\"color:#ffffff;background-color:#a43725\"><strong class=\"source-bold\">否</strong></span><strong class=\"source-bold\">の分かれ目</strong>　<span data-source-border=\"brown\" data-source-border-style=\"dotted\" style=\"border:1px dotted #a43725\"><strong class=\"source-bold\">第一次世界大戦後の革命政党</strong></span></h3>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中国国民党</strong></span> ［1919］ ……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">孫文</strong></span>の指導で<strong class=\"source-bold\">中華革命党</strong>を改組・改称</p>\n<blockquote><p><span data-source-color=\"green\" style=\"color:#315837\">▶</span><strong class=\"source-bold\">全国民に開かれた大衆政党</strong>となり、<strong class=\"source-bold\">北京政府の打倒</strong>を目指した</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span>当初は、南部の軍閥と組んで、<strong class=\"source-bold\">広東軍政府</strong>を樹立</p></blockquote>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中国共産党</strong></span> ［1921］ ……初代委員長（のち総書記）は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">陳独秀</strong></span></p>\n<blockquote><p><span data-source-color=\"green\" style=\"color:#315837\">▶</span><strong class=\"source-bold\">上海</strong>で結成。当初の党員は50名程度</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span>結成当初は<strong class=\"source-bold\">コミンテルンの指導下</strong>にあった</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span>コミンテルンの方針に従って、<strong class=\"source-bold\">国民党との合作路線</strong>をとる</p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "314": "<h2>314</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第17回</strong></span> 戦間期の東アジア</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ソ連の支援でモンゴルが社会主義国として独立！</strong></span></h4>\n<p>ここで、モンゴルの状況を見ておこう。日本や中国がシベリア出兵をした時、外モンゴルには中国軍が侵攻して、その後、ロシア革命に反対する白軍も攻めてきたんだ。でも、<strong class=\"source-bold\">モンゴル人民党</strong>（要は共産党だよ）の<strong class=\"source-bold\">チョイバルサン</strong>らが<strong class=\"source-bold\">ソ連の赤軍の支援を受けて勝利</strong>し、中華民国から独立して<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">モンゴル人民共和国</strong></span>を建てたよ。これは、<strong class=\"source-bold\">ソ連に次いで史上2番目の社会主義国</strong>だよ。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">クローズアップ</span> <span data-source-color=\"black\" data-source-background=\"pink\" style=\"color:#222222;background-color:#f0a0a0\"><strong class=\"source-bold\">北伐の展開</strong></span></h3>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1次国共合作</strong></span>の成立 ［1924.1］ ……<strong class=\"source-bold\">中国国民党一全大会</strong>で決定</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><strong class=\"source-bold\"><ruby>孫文<rt>そんぶん</rt></ruby>の病死</strong> ［1925.3］ ……軍への影響力が強い<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>蔣介石<rt>しょうかいせき</rt></ruby></strong></span>が実権を握る</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>五<rt>ご</rt></ruby>・<ruby>三〇<rt>さんじゅう</rt></ruby>運動</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">五・三〇事件</strong></span>】</strong> ［1925］ ……<strong class=\"source-bold\">民衆の反帝国主義運動</strong>が再び高揚</p>\n<blockquote><p><span data-source-color=\"green\" style=\"color:#315837\">▶</span>国民党内での<strong class=\"source-bold\">共産党の影響力増大</strong>が明らかとなる</p></blockquote>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>広州<rt>こうしゅう</rt></ruby>国民政府</strong></span>（<strong class=\"source-bold\">中華民国国民政府</strong>）成立 ［1925.7］ ……主席は<ruby>汪兆銘<rt>おうちょうめい</rt></ruby></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民革命軍</strong></span>の結成 ［1925］ ……総司令官：蔣介石</p>\n<blockquote><p><span data-source-color=\"green\" style=\"color:#315837\">➡</span><strong class=\"source-bold\">国民政府内での内部対立</strong>が発生……軍（蔣介石）vs.党・政府（反蔣介石）</p></blockquote>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>北伐<rt>ほくばつ</rt></ruby></strong></span>（<strong class=\"source-bold\">第1次北伐</strong>）開始［1926.7］ ……広州から開始<span data-source-color=\"green\" style=\"color:#315837\">➡</span><strong class=\"source-bold\"><ruby>武漢<rt>ぶかん</rt></ruby></strong>を占領［1926.10］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><strong class=\"source-bold\">武漢政府</strong>の樹立 ［1927.1］ ……<strong class=\"source-bold\">国民党左派と共産党</strong>が協力。中心は<strong class=\"source-bold\">汪兆銘</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>上海<rt>シャンハイ</rt></ruby>クーデタ</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">四・一二クーデタ</strong></span>】</strong>［1927.4］……<strong class=\"source-bold\">蔣介石</strong>が強行した<strong class=\"source-bold\">反共クーデタ</strong></p>\n<blockquote><p><span data-source-color=\"green\" style=\"color:#315837\">▶</span>蔣介石は共産党員を<ruby>弾圧<rt>だんあつ</rt></ruby>・殺害し、<strong class=\"source-bold\">第1次国共合作が崩壊</strong>（国共分裂）</p></blockquote>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>南京<rt>ナンキン</rt></ruby>国民政府</strong></span>成立 ［1927.4］ ……<strong class=\"source-bold\">蔣介石</strong>が<strong class=\"source-bold\">国民党右派</strong>を集めて成立</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><strong class=\"source-bold\">北伐再開</strong>（<strong class=\"source-bold\">第2次北伐</strong>）［1928.4］ ……<strong class=\"source-bold\">国民党のみ</strong>で推進</p>\n<blockquote><p><span data-source-color=\"green\" style=\"color:#315837\">➡</span>日本の<strong class=\"source-bold\"><ruby>山東<rt>さんとう</rt></ruby>出兵</strong> ［1927〜28］ ……北伐を<ruby>阻止<rt>そし</rt></ruby>しようとする<strong class=\"source-bold\">日本軍が出兵</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span><strong class=\"source-bold\"><ruby>済南事件<rt>せいなんじけん</rt></ruby></strong> ［1928.5］ ……日本軍と北伐軍の<ruby>衝突<rt>しょうとつ</rt></ruby></p></blockquote>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span>北伐軍の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>北京<rt>ペキン</rt></ruby>制圧</strong></span>［1928.6］……日本軍の支援を受ける<strong class=\"source-bold\"><ruby>奉天軍閥<rt>ほうてんぐんばつ</rt></ruby></strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>張作霖<rt>ちょうさくりん</rt></ruby></strong></span>を破る</p>\n<blockquote><p><span data-source-color=\"green\" style=\"color:#315837\">➡</span>日本の<strong class=\"source-bold\">関東軍</strong>による<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">張作霖爆殺事件</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">奉天事件</strong></span>】</strong> ［1928.6］</p></blockquote>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">北伐の完成</strong></span> ［1928.12］ ＝<strong class=\"source-bold\">国民革命（中国統一）の完成</strong></p>\n<blockquote><p><span data-source-color=\"green\" style=\"color:#315837\">▶</span>張作霖の子：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>張学良<rt>ちょうがくりょう</rt></ruby></strong></span>が<strong class=\"source-bold\">国民党に<ruby>帰順<rt>きじゅん</rt></ruby></strong>し、北伐は一応完成</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span>蔣介石は南部で武装<ruby>蜂起<rt>ほうき</rt></ruby>を狙う<strong class=\"source-bold\">共産党を攻撃</strong></p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">「<ruby>連<rt>れん</rt></ruby>ソ・<ruby>容共<rt>ようきょう</rt></ruby>・<ruby>扶助工農<rt>ふじょこうのう</rt></ruby>」に基づいて、第1次国共合作ができた！</strong></span></h4>\n<p><ruby>五<rt>ご</rt></ruby>・<ruby>四<rt>し</rt></ruby>運動の影響を受けた孫文と<strong class=\"source-bold\">コミンテルン</strong>は、少しずつ接触し始めたよ。これは、孫文が軍事面や経済面で外国の支援を必要としていたってことだ。そして1923年には<strong class=\"source-bold\">孫文＝ヨッフェ会談</strong>が開かれ、「革命勢力を国民党に結集しよう！」って合意した。この時、コミンテルンが「<strong class=\"source-bold\">中国を社会主義にはしない</strong>」って確認しているんだ。この合意があったから、孫文も<strong class=\"source-bold\">共産党と連携</strong>しようって思ったんだね。</p>",
  "315": "<h2>315</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">孫文の国民革命と北伐</u></p>\n<p>こうして1924年、広州で開かれた<strong class=\"source-bold\">中国国民党一全大会</strong> <strong class=\"source-bold\">【</strong>中国国民党第1回全国代表大会<strong class=\"source-bold\">】</strong>で国民党の組織改革をおこない、「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">連ソ</strong></span>・<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">容共</strong></span>・<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">扶助工農</strong></span>」（ソ連と連携する・共産党を受け入れる・労働者と農民を助ける）の新政策が決定され、<strong class=\"source-bold\">国民党と共産党が協力</strong>する<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1次国共合作</strong></span>が成立したよ。ただ、この時は圧倒的に国民党のほうが大きかったから（当時の党員数は国民党が約5万人、共産党が1000人以下だ）、対等な協力にはならない。<strong class=\"source-bold\">共産党員が個人の資格として国民党に入党</strong>（つまり、<strong class=\"source-bold\">国民党が共産党を吸収</strong>）して、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">北伐</strong></span>（<strong class=\"source-bold\">北洋軍閥と北京政府の打倒による中国統一</strong>）を進めることになったんだ。そして、軍の幹部を養成するために、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">蔣介石</strong></span>を校長とする<strong class=\"source-bold\"><ruby>黄埔<rt>こうほ</rt></ruby>軍官学校</strong>がつくられたよ。この時、政治部副主任だったのが<strong class=\"source-bold\">共産党の<ruby>周恩来<rt>しゅうおんらい</rt></ruby></strong>だ。この二人は、あとで<ruby>因縁<rt>いんねん</rt></ruby>の再会をするからね。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">「革命いまだならず……」の遺言を残して孫文が病死！</strong></span></h4>\n<p>1925年、「いよいよ北京政府打倒に向かうぞ！」って時に、<strong class=\"source-bold\">孫文が病死</strong>した。孫文は「<strong class=\"source-bold\">革命いまだならず</strong>……民衆を立ち上がらせ力を合わせよ」との遺言を残し、さらに「<strong class=\"source-bold\">ソ連との連携を維持</strong>して、軍閥や帝国主義と戦え」って言ってたんだけど、孫文の死後すぐに全国的な大衆運動が起こったんだ！。</p>\n<p>1925年、上海の日本人経営の<ruby>紡績<rt>ぼうせき</rt></ruby>工場でのストライキから起こった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">五・三〇運動</strong></span>は、労働者が射殺された事件をきっかけに立ち上がった民衆が<ruby>租界<rt>そかい</rt></ruby>の警察と衝突すると、<strong class=\"source-bold\">全国的な反帝国主義運動</strong>に発展したよ。その後、<strong class=\"source-bold\">共産党員の影響</strong>が強まっていた<strong class=\"source-bold\">国民政府の支援</strong>で<ruby>列強<rt>れっきょう</rt></ruby>の租界を回収する運動が起こり、さらに<ruby>香港<rt>ホンコン</rt></ruby>ではイギリスに反発する<strong class=\"source-bold\">省港スト</strong>が1年以上続いたんだ。そして五・三〇運動は、大衆運動の力を再び見せつけると同時に、<strong class=\"source-bold\">国民党内部での対立</strong>を引き起こしていくんだよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">いよいよ北伐の開始。しかし、第1次国共合作は崩壊！</strong></span></h4>\n<p>1925年、<ruby>広東<rt>カントン</rt></ruby>軍政府が再編されて、<strong class=\"source-bold\">国共合作</strong>による政府として<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">広州国民政府</strong></span>（正式には<strong class=\"source-bold\">中華民国国民政府</strong>）ができた。そして、北伐のための軍隊として、<strong class=\"source-bold\">黄埔軍官学校の学生</strong>を中心に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民革命軍</strong></span>が結成されたよ。この時、国民政府の<ruby>主席<rt>しゅせき</rt></ruby>となったのは汪兆銘、<strong class=\"source-bold\">国民革命軍の総司令官</strong>となったのは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">蔣介石</strong></span>だ。軍人たちの多くは蔣介石の教え子だもんね。</p>\n<p>ただ、政府内ではすでに分裂が始まっていた。五・三〇運動で強くなった<strong class=\"source-bold\">共産党を警戒する右派</strong>は蔣介石と組み、<strong class=\"source-bold\">共産党と一緒に民衆運動を進めようとする左派</strong>と対立し始めたけど、軍の指揮権を握る<strong class=\"source-bold\">蔣介石を中心</strong>に、1926年7月<strong class=\"source-bold\">北伐（第1次北伐）</strong>が始まった。こんな状態で本当に勝てるのかな。</p>\n<blockquote><p>北伐が始まった時に、すでに政府内では右派と左派の対立が始まっていたんだ</p></blockquote>\n<p>しかし、いざ始まってみると<strong class=\"source-bold\">北伐軍は予想以上の快進撃</strong>。一気に<ruby>湖南<rt>こなん</rt></ruby>省を制圧すると、たったの3カ月で<strong class=\"source-bold\">武漢</strong>を占領し、さらに<ruby>江西<rt>こうせい</rt></ruby>省から<ruby>福建<rt>ふっけん</rt></ruby>省、</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "316": "<h2>316</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第17回</strong></span> 戦間期の東アジア</p>\n<p>ついには北部の<ruby>陝西<rt>せんせい</rt></ruby>省にまで勢力をのばしたんだ。この快進撃のウラには、農民を中心とする<strong class=\"source-bold\">民衆の支持</strong>があったよ。だって「<strong class=\"source-bold\"><ruby>扶助工農<rt>ふじょこうのう</rt></ruby></strong>」でしょ。農民は「<ruby>北伐<rt>ほくばつ</rt></ruby>軍はイジワルな地主を倒して、自分たちを助けてくれる」って信じていたからね。これを宣伝したのは共産党員だから、民衆運動に対する<strong class=\"source-bold\">共産党の影響力が強まった</strong>。一方で、戦闘に勝っているから国民革命軍総司令官の<strong class=\"source-bold\"><ruby>蔣介石<rt>しょうかいせき</rt></ruby>も強くなる</strong>。だから、国民党では<strong class=\"source-bold\">右派と左派の主導権争い</strong>が激しくなったんだ。</p>\n<p>この主導権争いで、最初に手を打ったのは左派だよ。1927年、<strong class=\"source-bold\">国民党左派と共産党</strong>は<ruby>広州<rt>こうしゅう</rt></ruby>にあった<strong class=\"source-bold\">国民政府を<ruby>武漢<rt>ぶかん</rt></ruby>に<ruby>遷都<rt>せんと</rt></ruby></strong>して（<strong class=\"source-bold\">武漢政府</strong>）、<strong class=\"source-bold\"><ruby>汪兆銘<rt>おうちょうめい</rt></ruby></strong>を最高指導者として蔣介石から権力を奪おうとした。でも、<strong class=\"source-bold\">軍の指揮権は蔣介石が握ったまま</strong>だ。一方、<ruby>上海<rt>シャンハイ</rt></ruby>に向かっていた蔣介石も、共産党の影響が強まっていることを思い知らされた。<strong class=\"source-bold\">上海では共産党が指導する武装<ruby>蜂起<rt>ほうき</rt></ruby></strong>が起きて、焦ったイギリスやアメリカが出兵する事態となり、さらに国民革命軍が<ruby>南京<rt>ナンキン</rt></ruby>に着いた時、共産党系の兵士が外国領事館を<ruby>襲撃<rt>しゅうげき</rt></ruby>する事件（<strong class=\"source-bold\">南京事件</strong>）が起きた。この時、蔣介石は「<strong class=\"source-bold\">共産党と手を切る</strong>」という約束をして、イギリスやアメリカなど<ruby>列強<rt>れっきょう</rt></ruby>との関係を深めたんだ。</p>\n<p>そして1927年4月12日、ついに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">蔣介石</strong></span>による<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">上海クーデタ</strong></span>が起きたよ。<strong class=\"source-bold\"><ruby>列強<rt>れっきょう</rt></ruby></strong>や<strong class=\"source-bold\"><ruby>浙<rt>せっ</rt></ruby><ruby>江財閥<rt>こうざいばつ</rt></ruby></strong>と手を組んだ蔣介石軍は<strong class=\"source-bold\">共産党員を徹底的に取り締まり</strong>、武器を取り上げ、反発する者は虐殺した！。こうして<strong class=\"source-bold\">第1次国共合作は崩壊</strong>したよ。</p>\n<p>その後、蔣介石は<strong class=\"source-bold\">国民党右派</strong>を集めて、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">南京国民政府</strong></span>を樹立した。武漢政府の<strong class=\"source-bold\">国民党左派</strong>は蔣介石に対抗しようとしたんだけど、最終的には共産党と手を切って<strong class=\"source-bold\">南京政府に合流</strong>するしかなかった。こうして、<strong class=\"source-bold\">国民党のみになった南京国民政府</strong>では、<strong class=\"source-bold\">蔣介石が主導権</strong>を握ったんだよ。</p>\n<h3><strong class=\"source-bold\">〈北伐と日本の進出〉</strong></h3>\n<blockquote><p>北伐軍の動きと日本の動きをあわせて見てね！</p></blockquote>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-marker=\"point\" data-source-color=\"black\" style=\"color:#222222\">○</span> 奉天</td><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">張作霖爆殺事件<br>［1928.6］</strong></span> <span data-source-marker=\"cross\" data-source-color=\"red\" style=\"color:#e52715\">×</span></td></tr><tr><td><span data-source-marker=\"point\" data-source-color=\"black\" style=\"color:#222222\">○</span> 北京</td><td><span data-source-border=\"black\" style=\"border:1px solid #222222\">張作霖の退路</span> <span data-source-marker=\"dashed-arrow\" data-source-color=\"green\" style=\"color:#315837\">⇢</span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">日本の大陸進出</strong></span></td><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">満洲進出</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\">➡</span> <span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">山東出兵</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\">➡</span></td></tr><tr><td><span data-source-border=\"brown\" style=\"border:1px solid #a43725\">済南事件<br>［1928.5］</span></td><td><span data-source-marker=\"cross\" data-source-color=\"red\" style=\"color:#e52715\">×</span></td></tr><tr><td><span data-source-marker=\"point\" data-source-color=\"black\" style=\"color:#222222\">○</span> 南京</td><td><span data-source-border=\"pink\" style=\"border:1px solid #f0a0a0\">南京国民政府［1927〜］</span></td></tr><tr><td><span data-source-marker=\"star\" data-source-color=\"black\" style=\"color:#222222\">☆</span> 上海</td><td><span data-source-border=\"pink\" style=\"border:1px solid #f0a0a0\">上海クーデタ［1927.4］</span></td></tr><tr><td><span data-source-marker=\"point\" data-source-color=\"black\" style=\"color:#222222\">○</span> 武漢</td><td><span data-source-border=\"pink\" style=\"border:1px solid #f0a0a0\">武漢政府［1927］</span></td></tr><tr><td><span data-source-marker=\"point\" data-source-color=\"black\" style=\"color:#222222\">○</span> 広州</td><td><span data-source-border=\"pink\" style=\"border:1px solid #f0a0a0\">広州国民政府［1925〜］</span></td></tr></tbody></table></div>\n<p><span data-source-marker=\"arrow\" data-source-color=\"pink\" style=\"color:#f0a0a0\">➡</span> 第1次北伐（国共合作で進める）</p>\n<p><span data-source-marker=\"arrow\" data-source-color=\"brown\" style=\"color:#a43725\">➡</span> 第2次北伐（国民党のみ）</p>",
  "317": "<h2>317</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">孫文の国民革命と北伐</u></p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">北伐軍と日本軍との衝突も起きたけど……国民党のみで北伐完成！</strong></span></h4>\n<p>1928年、蔣介石は<strong class=\"source-bold\">国民党のみ</strong>で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">北伐を再開</strong></span>したよ（<strong class=\"source-bold\">第2次北伐</strong>）。目標は<ruby>北京<rt>ペキン</rt></ruby>！　北京政府の実権を握る<strong class=\"source-bold\"><ruby>奉天軍閥<rt>ほうてんぐんばつ</rt></ruby></strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>張作霖<rt>ちょうさくりん</rt></ruby></strong></span>は<strong class=\"source-bold\">日本軍の支援</strong>を受けていたんだけど、<strong class=\"source-bold\">日本も張作霖を利用して<ruby>満洲<rt>まんしゅう</rt></ruby>に進出</strong>していたから、蔣介石軍が北京にくると<ruby>厄介<rt>やっかい</rt></ruby>だ。だから、<ruby>田中義一<rt>たなかぎいち</rt></ruby>内閣は日本人の居留民の保護を口実に<strong class=\"source-bold\"><ruby>山東<rt>さんとう</rt></ruby>に出兵</strong>して、実際に軍事衝突も起きちゃった（<strong class=\"source-bold\"><ruby>済南事件<rt>せいなんじけん</rt></ruby></strong>）。こうした北伐の妨害に対して、蔣介石は日本軍との衝突を避けて北上したから、大きな戦闘は起きなかったけど、日中関係は悪化し始め、中国での反帝国主義運動は、明確に「反日」運動になったんだ。</p>\n<p>そしてついに、<strong class=\"source-bold\">北伐軍は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">北京</strong></span>に攻め込んだ</strong>。蔣介石軍はすでに約60万人にまで<ruby>膨<rt>ふく</rt></ruby>れ上がっていたから、<strong class=\"source-bold\">張作霖</strong>はほとんど抵抗できずに<strong class=\"source-bold\">北京を捨てた</strong>よ。この時、<strong class=\"source-bold\">張作霖</strong>は「悪あがきしないで<strong class=\"source-bold\"><ruby>奉天<rt>ほうてん</rt></ruby>へと<ruby>撤退<rt>てったい</rt></ruby></strong>する」と、<strong class=\"source-bold\">蔣介石</strong>も「張作霖が撤退するなら<strong class=\"source-bold\"><ruby>追撃<rt>ついげき</rt></ruby>しない</strong>」と、それぞれ日本に伝えていたんだけど、満洲にいた<strong class=\"source-bold\">現地の日本軍（<ruby>関東軍<rt>かんとうぐん</rt></ruby>）</strong>が、「もはや利用できないから、張作霖は消してしまえ」とばかりに、<strong class=\"source-bold\">張作霖の乗る特別列車を爆破</strong>した！。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">張作霖爆殺事件</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">奉天事件</strong></span>】</strong>だ。</p>\n<blockquote><p>張作霖爆殺事件のころから、日本では軍部の暴走が始まってしまうんだ</p></blockquote>\n<p><ruby>親父<rt>おやじ</rt></ruby>を殺された<strong class=\"source-bold\">張作霖の息子</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>張学良<rt>ちょうがくりょう</rt></ruby></strong></span>は、蔣介石に「もう、北伐軍による中国統一を阻止しない」と伝えたよ。そりゃ、自分の本拠地だった満洲を取られ、親父を爆殺されたんだもん、日本に協力する理由は全くない。こうして、満洲（<strong class=\"source-bold\"><ruby>東三省<rt>とうさんしょう</rt></ruby></strong>）を支配する<strong class=\"source-bold\">張学良が国民党に<ruby>帰順<rt>きじゅん</rt></ruby></strong>し、ひとまず<strong class=\"source-bold\">南京国民政府による中国統一</strong>が完成したんだ（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">北伐完成</strong></span>）。</p>\n<p>これ以後、蔣介石は「外から侵略してくる日本よりも、まずは国内の統一を乱す共産党を<ruby>潰<rt>つぶ</rt></ruby>す！」として、<strong class=\"source-bold\">共産党への攻撃</strong>を始めるんだけど、国内では共産党に加えて反蔣介石派が自立して、実際はまだバラバラだったんだよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">蔣介石が北伐を完成させたころ、共産党は何をやってたんだろう？</strong></span></h4>\n<p>続いて、<strong class=\"source-bold\">上海クーデタ後の共産党</strong>の動きを見ておこう。共産党のなかでは、これまで主導権を握っていた<strong class=\"source-bold\"><ruby>陳独秀<rt>ちんどくしゅう</rt></ruby></strong>が「どうして上海クーデタを防げなかったのか？」と責任を問われて<strong class=\"source-bold\">失脚した</strong>んだ。これはコミンテルン（要はソ連）が、中国での失敗の責任を「すべて陳独秀が悪い」ってことにしたからだよ。</p>\n<p>これ以降、中国共産党は<strong class=\"source-bold\">コミンテルンの指示</strong>を受けて<strong class=\"source-bold\">都市で武装蜂起</strong>するんだけど、ことごとく失敗した。例えば、1927年8月に<ruby>朱徳<rt>しゅとく</rt></ruby>らが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>紅軍<rt>こうぐん</rt></ruby></strong></span>（共産党軍）を率いて<strong class=\"source-bold\"><ruby>南昌<rt>なんしょう</rt></ruby>蜂起</strong>を起こしたけど失敗し、さらに残った連中が<strong class=\"source-bold\"><ruby>海豊<rt>かいほう</rt></ruby>・<ruby>陸豊<rt>りくほう</rt></ruby></strong>にソヴィエト政権を建設したけど、やはり<strong class=\"source-bold\">国民党軍に潰されちゃった</strong>。</p>\n<p>こうしたなかで、これまでとは違う路線を打ち出したのは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>毛沢東<rt>もうたくとう</rt></ruby></strong></span>だ。彼は「山に</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "318": "<h2>318</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第17回</strong></span> 戦間期の東アジア</p>\n<p>上れ！　山間部の農村に拠点をつくり、<strong class=\"source-bold\">農村から都市を包囲する</strong>」という戦略を打ち出した。まず<strong class=\"source-bold\"><ruby>井岡山<rt>せいこうざん</rt></ruby></strong>に拠点（ソヴィエト区）を建設し、地主から土地を奪って農民に分配する<strong class=\"source-bold\">土地改革</strong>をおこないながら、貧乏な農民を味方につけるゲリラ戦術で、<strong class=\"source-bold\"><ruby>華南<rt>かなん</rt></ruby>に根拠地を増やしていった</strong>。<ruby>毛沢東<rt>もうたくとう</rt></ruby>は「政権は鉄砲から生まれる！」と唱えて農民たちを武装させ、<strong class=\"source-bold\"><ruby>紅軍<rt>こうぐん</rt></ruby>を拡大</strong>したんだ。</p>\n<blockquote><p>「農村から都市を包囲する」毛沢東の路線は、マルクスとはずいぶん違うよね</p></blockquote>\n<p>そして1931年、都市の紅軍が毛沢東の率いる農村の紅軍と合流し、<strong class=\"source-bold\">華南の拠点（ソヴィエト区）を統合</strong>して、<strong class=\"source-bold\"><ruby>江西<rt>こうせい</rt></ruby>省</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>瑞金<rt>ずいきん</rt></ruby></strong></span>を首都とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中華ソヴィエト共和国臨時政府</strong></span>が樹立され、表向きは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">毛沢東</strong></span>が主席になった。ただ、実際に権力を握っていたのは、コミンテルンとのつながりを持つ<strong class=\"source-bold\">モスクワ留学派</strong>だよ。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">日本の侵略と国共内戦</strong></span></h3>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">クローズアップ</span> <span data-source-color=\"black\" data-source-background=\"pink\" style=\"color:#222222;background-color:#f0a0a0\"><strong class=\"source-bold\">第2次国共合作までの流れ</strong></span></h3>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>満洲<rt>まんしゅう</rt></ruby>事変</strong></span> ［1931.9〜33.5］ ……日本の<strong class=\"source-bold\"><ruby>関東軍<rt>かんとうぐん</rt></ruby></strong>による満洲への<ruby>侵略<rt>しんりゃく</rt></ruby></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>柳条湖<rt>りゅうじょうこ</rt></ruby>事件</strong></span> ［1931.9］ ……関東軍による<strong class=\"source-bold\">南満洲鉄道の爆破事件</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">満洲国</strong></span>成立 ［1932.3］ ……<ruby>清<rt>シン</rt></ruby>朝最後の皇帝：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>溥儀<rt>ふぎ</rt></ruby></strong></span>が<ruby>執政<rt>しっせい</rt></ruby>（<strong class=\"source-bold\">1934年から皇帝</strong>）</p>\n<blockquote><p><span data-source-color=\"green\" style=\"color:#315837\">➡</span><strong class=\"source-bold\"><ruby>熱河<rt>ねっか</rt></ruby></strong>を占領し、満洲国に編入 ［1933.2〜3］ ……<strong class=\"source-bold\"><ruby>塘沽<rt>タンクー</rt></ruby>停戦協定</strong> ［1933］</p></blockquote>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span>日本の「<strong class=\"source-bold\"><ruby>華北<rt>かほく</rt></ruby>分離工作</strong>」 ……華北に<ruby>傀儡<rt>かいらい</rt></ruby>政権を設立</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><strong class=\"source-bold\"><ruby>冀東<rt>きとう</rt></ruby>防共自治政府</strong> ［1935］ ……日本が<ruby>河北<rt>かほく</rt></ruby>省東北部に成立させた傀儡政権</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><ruby>蔣介石<rt>しょうかいせき</rt></ruby>の<ruby>独裁<rt>どくさい</rt></ruby>体制強化</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><strong class=\"source-bold\"><ruby>幣制<rt>へいせい</rt></ruby>改革</strong> ［1935.11］ ……国民政府が貨幣を統一し、<strong class=\"source-bold\">管理通貨制度に移行</strong></p>\n<blockquote><p><span data-source-color=\"green\" style=\"color:#315837\">▶</span>権力を強めた蔣介石は、<strong class=\"source-bold\"><ruby>抗日<rt>こうにち</rt></ruby>よりも反共政策</strong>を重視し、<ruby>執拗<rt>しつよう</rt></ruby>に<strong class=\"source-bold\">共産党を攻撃</strong></p></blockquote>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>長征<rt>ちょうせい</rt></ruby></strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>大西遷<rt>だいせいせん</rt></ruby></strong></span>】</strong> ［1934.10〜36.10］ ……共産党は瑞金を撤退して大移動</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><strong class=\"source-bold\"><ruby>遵義<rt>じゅんぎ</rt></ruby>会議</strong> ［1935］ ……党内での主導権が<strong class=\"source-bold\">モスクワ留学派</strong>から<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">毛沢東</strong></span>に移る</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>八<rt>はち</rt></ruby>・<ruby>一<rt>いち</rt></ruby>宣言</strong></span> <strong class=\"source-bold\">【抗日救国のために全<ruby>同胞<rt>どうほう</rt></ruby>に告げる書】</strong> ［1935.8］</p>\n<blockquote><p><span data-source-color=\"green\" style=\"color:#315837\">▶</span>日本の侵略に対して、<strong class=\"source-bold\">内戦の停止</strong>と<strong class=\"source-bold\">抗日民族統一戦線</strong>の結成を訴えた</p></blockquote>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>西安<rt>せいあん</rt></ruby>事件</strong></span>［1936.12.12］……八・一宣言に共鳴した<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>張学良<rt>ちょうがくりょう</rt></ruby></strong></span>が<strong class=\"source-bold\">蔣介石を武力で監禁</strong></p>\n<blockquote><p><span data-source-color=\"green\" style=\"color:#315837\">▶</span>共産党の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>周恩来<rt>しゅうおんらい</rt></ruby></strong></span>らが説得。蔣介石が内戦停止と一致抗日に合意したとされる</p></blockquote>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第2次国共合作</strong></span><strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">抗日民族統一戦線</strong></span>】</strong>成立［1937］……日中戦争<ruby>勃発<rt>ぼっぱつ</rt></ruby>の直後に成立</p>\n<blockquote><p><span data-source-color=\"green\" style=\"color:#315837\">▶</span>紅軍（共産党軍）は<strong class=\"source-bold\"><ruby>八路軍<rt>はちろぐん</rt></ruby></strong> <strong class=\"source-bold\">【第八路軍】</strong>として、<strong class=\"source-bold\">蔣介石の指揮下</strong>に入る</p></blockquote>",
  "319": "<h2>319</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">日本の侵略と国共内戦</u></p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">柳条湖事件をきっかけに満洲事変が勃発！</strong></span></h4>\n<p>日本は、第一次世界大戦の時に輸出が拡大して、むちゃくちゃ経済が発展したんだけど、戦後は輸出が減って<strong class=\"source-bold\">戦後<ruby>恐慌<rt>きょうこう</rt></ruby></strong>が起こり、1923年には追い打ちをかけるように<strong class=\"source-bold\">関東大震災</strong>が起き、1927年には<strong class=\"source-bold\">金融恐慌</strong>も発生した。しかも1929年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">世界恐慌</strong></span>の影響も受けて、日本は<ruby>不況<rt>ふきょう</rt></ruby>のどん底におちいった。こうした状況を打破するため、軍部は独断で<strong class=\"source-bold\">満洲の直接支配</strong>を狙ったんだよ。満洲は<strong class=\"source-bold\">鉄鉱石や石炭などの資源</strong>もあるし、日本にとっては最大の投資先だったからね。</p>\n<p>1931年、<strong class=\"source-bold\">満洲の日本軍（関東軍）</strong>は、<ruby>奉天<rt>ほうてん</rt></ruby>郊外の柳条湖で<strong class=\"source-bold\">南満洲鉄道の列車を爆破</strong>し、「これは中国軍がやったから自衛戦争だ！」として中国との戦闘を始めた。この<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">柳条湖事件</strong></span>から始まる一連の軍事行動が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">満洲事変</strong></span>だよ。関東軍は一気に満洲全域を制圧すると、<strong class=\"source-bold\">清朝最後の皇帝</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">溥儀</strong></span>を執政として、<strong class=\"source-bold\">日本の傀儡国家</strong>「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">満洲国</strong></span>」を建てたんだ。のちに溥儀は皇帝になるんだけど、<strong class=\"source-bold\">最初は皇帝じゃない</strong>よ。</p>\n<p>日本の軍事行動に対して、<strong class=\"source-bold\">中国は国際連盟に訴えた</strong>。そして、国際連盟から派遣された<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">リットン調査団</strong></span>（“リットン”は団長の名前）が現地を調査して、「<strong class=\"source-bold\">満洲事変は</strong>自衛戦争ではなく<strong class=\"source-bold\">日本の侵略行為</strong>で、<strong class=\"source-bold\">“満洲国”は認められない</strong>」との報告書を発表したよ。とはいっても、<strong class=\"source-bold\">日本の満洲における特権は大幅に認められた</strong>から、日本に「満洲から撤退しろ！」って言ってるわけじゃないんだけど、連盟が<strong class=\"source-bold\">経済制裁を打ち出そうとした</strong>から、日本はこれを不満として<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国際連盟を脱退</strong></span>したんだ。</p>\n<p>しかも、この間にも日本の軍事行動が続いていたよ。まず、1932年には日本人殺害事件を口実に、<ruby>上海<rt>シャンハイ</rt></ruby>でも中国軍との軍事衝突を起こした（<strong class=\"source-bold\">上海事変</strong>）。これって、<strong class=\"source-bold\">国際社会の目を満洲からそらすため</strong>って言われてるけど、こんなの余計目立つよ……。さらに、満洲の隣の<strong class=\"source-bold\"><ruby>熱河<rt>ねっか</rt></ruby>を占領</strong>すると、「満洲国の領土だ！」と言って編入した。このあと国民政府と<strong class=\"source-bold\"><ruby>塘沽<rt>タンクー</rt></ruby>停戦協定</strong>を結んで戦闘はいったん終わり、中国側は<strong class=\"source-bold\">満洲国</strong>の存在と<strong class=\"source-bold\">熱河の満洲国編入</strong>を事実上認めることになったんだ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">日本は華北で勢力拡大、中国内は蔣介石の共産党攻撃で内戦激化！</strong></span></h4>\n<p>この時期の中国をめぐる情勢は、なかなか難しいよね。というのも、<strong class=\"source-bold\">蔣介石の国民党、共産党、日本</strong>の3つの動きを一緒に考えないといけないからね。ここは次ページの地図<span data-source-color=\"white\" data-source-background=\"green\" style=\"color:#ffffff;background-color:#859476\"><strong class=\"source-bold\">➡P.320</strong></span>も見ながら、1つひとつ確認してね。</p>\n<blockquote><p>日本は「華北分離工作」、蔣介石は「共産党弾圧」、共産党は「長征」、3つの動きを一緒に考えよう！</p></blockquote>\n<p>まずは<strong class=\"source-bold\">日本の動き</strong>を見てみよう。満洲事変が起きたのと同じころ、東京では、政党内閣に反発した<strong class=\"source-bold\">海軍の青年将校</strong>と<ruby>右翼<rt>うよく</rt></ruby>が、首相官邸で<strong class=\"source-bold\"><ruby>犬養毅<rt>いぬかいつよし</rt></ruby>首相を暗殺</strong>する<strong class=\"source-bold\"><ruby>五<rt>ご</rt></ruby>・<ruby>一五<rt>いちご</rt></ruby>事件</strong>が起きたんだ。これって「軍部の言うこと聞かないヤツは、首相でも殺す」ってことだよ。こうして軍部の発言力がむちゃくちゃ強くなって、日本では<strong class=\"source-bold\">政党政治が終わり</strong>を告げた。さらに、<strong class=\"source-bold\">国際連盟の脱退、ワシント</strong></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "320": "<h2>320</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第17回</strong></span> 戦間期の東アジア</p>\n<p><strong class=\"source-bold\">ン・ロンドン両海軍軍縮条約の<ruby>破棄<rt>はき</rt></ruby></strong>で、国際的な孤立を深めていたんだ。そして中国では、<ruby>華北<rt>かほく</rt></ruby>に中国人の<ruby>傀儡<rt>かいらい</rt></ruby>政権をつくって国民政府の支配から分離させる「<strong class=\"source-bold\">華北分離工作</strong>」を進め、<strong class=\"source-bold\"><ruby>冀東<rt>きとう</rt></ruby>防共自治政府</strong>を設立させた。こうした軍事行動は、中国人に相当の危機感を抱かせたよ。さらに、1936年には<strong class=\"source-bold\">陸軍の急進派将校（<ruby>皇道派<rt>こうどうは</rt></ruby>）</strong>が大臣を暗殺する<strong class=\"source-bold\"><ruby>二<rt>に</rt></ruby>・<ruby>二六<rt>にろく</rt></ruby>事件</strong>が起きて、日本では<strong class=\"source-bold\">軍部による政治支配</strong>が止められなくなっていたんだ。</p>\n<p>一方、中国国内では<strong class=\"source-bold\">国民政府のゴタゴタ</strong>が続いていた。<strong class=\"source-bold\"><ruby>蔣介石<rt>しょうかいせき</rt></ruby></strong>は軍部の力を背景に<strong class=\"source-bold\">国民党内の反対派を抑え込み</strong>、さらに<strong class=\"source-bold\"><ruby>幣制<rt>へいせい</rt></ruby>改革</strong>によって経済的な支配を強めたよ。もともと<strong class=\"source-bold\">中国は銀本位制だった</strong>んだけど、世界<ruby>恐慌<rt>きょうこう</rt></ruby>後に各国が金本位制を停止したことで銀の国際価格が上がり、物価の上昇と銀の国外流出で、深刻な<ruby>不況<rt>ふきょう</rt></ruby>になっていた。そこで、アメリカやイギリスの支援を受けた国民政府が、国内に流通する銀を国有にして、政府系銀行（要するに<ruby>浙江財閥<rt>せっこうざいばつ</rt></ruby>）の発行する紙幣（<strong class=\"source-bold\"><ruby>法幣<rt>ほうへい</rt></ruby></strong>）のみに統一した。これが幣制改革だよ。こうして<strong class=\"source-bold\">中国は管理通貨制度になった</strong>んだけど、これって蔣介石と組んだ<strong class=\"source-bold\">浙江財閥が中国の金融を独占</strong>するってことだ。さらに、<strong class=\"source-bold\">新生活運動</strong>をおこなって、反共と将来の反日のために、社会生活を近代化して、近代的な国民精神を高めようとしたんだ。こうして権力を強めた蔣介石は、一気に<strong class=\"source-bold\">共産党への攻撃を激化</strong>させていくんだ。</p>\n<h3><strong class=\"source-bold\">〈国共対立と日本の侵略〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-marker=\"area\" data-source-color=\"pink\" data-source-pattern=\"vertical-lines\" style=\"color:#f0a0a0\">▥</span>「<strong class=\"source-bold\">満洲国</strong>」</td><td>［1932.3〜］</td></tr><tr><td><span data-source-marker=\"point\" data-source-color=\"black\" style=\"color:#222222\">○</span> 奉天</td><td><span data-source-border=\"pink\" style=\"border:1px solid #f0a0a0\">柳条湖事件<br>［1931.9］</span> <span data-source-marker=\"cross\" data-source-color=\"red\" style=\"color:#e52715\">×</span></td></tr><tr><td><span data-source-marker=\"point\" data-source-color=\"black\" style=\"color:#222222\">○</span> 北京</td><td><span data-source-border=\"black\" style=\"border:1px solid #222222\">盧溝橋事件<br>［1937.7］</span> <span data-source-marker=\"cross\" data-source-color=\"red\" style=\"color:#e52715\">×</span></td></tr><tr><td><span data-source-marker=\"point\" data-source-color=\"red\" style=\"color:#e52715\">●</span></td><td><span data-source-border=\"pink\" style=\"border:1px solid #f0a0a0\">冀東防共自治政府<br>［1935］</span></td></tr><tr><td><span data-source-marker=\"point\" data-source-color=\"green\" style=\"color:#859476\">●</span> 延安</td><td><span data-source-marker=\"dashed-arrow\" data-source-color=\"green\" style=\"color:#315837\">⇢</span></td></tr><tr><td><span data-source-marker=\"star\" data-source-color=\"red\" style=\"color:#e52715\">★</span></td><td><span data-source-border=\"black\" style=\"border:1px solid #222222\">西安事件［1936.12］</span></td></tr><tr><td><span data-source-marker=\"point\" data-source-color=\"brown\" style=\"color:#a43725\">●</span> <span data-source-color=\"brown\" style=\"color:#a43725\">南京</span></td><td><span data-source-border=\"brown\" style=\"border:1px solid #a43725\">南京国民政府（蔣介石）</span></td></tr><tr><td><span data-source-marker=\"point\" data-source-color=\"black\" style=\"color:#222222\">○</span> 上海</td><td></td></tr><tr><td><span data-source-marker=\"point\" data-source-color=\"black\" style=\"color:#222222\">○</span> 武漢</td><td></td></tr><tr><td><span data-source-marker=\"point\" data-source-color=\"black\" style=\"color:#222222\">○</span> 重慶</td><td></td></tr><tr><td><span data-source-border=\"brown\" style=\"border:1px solid #a43725\">国民政府の共産党攻撃</span></td><td><span data-source-color=\"brown\" style=\"color:#a43725\">➡</span></td></tr><tr><td><span data-source-marker=\"point\" data-source-color=\"green\" style=\"color:#859476\">●</span> 遵義</td><td></td></tr><tr><td>井岡山 <span data-source-marker=\"triangle\" data-source-color=\"green\" style=\"color:#859476\">▲</span></td><td></td></tr><tr><td><span data-source-marker=\"point\" data-source-color=\"green\" style=\"color:#859476\">●</span> 瑞金</td><td><span data-source-border=\"green\" style=\"border:1px solid #315837\">中華ソヴィエト共和国臨時政府［1931〜］</span></td></tr><tr><td><span data-source-marker=\"point\" data-source-color=\"black\" style=\"color:#222222\">○</span> 広州</td><td></td></tr><tr><td><span data-source-border=\"green\" style=\"border:1px solid #315837\">長征<br>［1934〜36］</span></td><td><span data-source-marker=\"dashed-arrow\" data-source-color=\"green\" style=\"color:#315837\">⇢</span></td></tr></tbody></table></div>\n<p><span data-source-color=\"brown\" style=\"color:#a43725\">➡</span> 国民党の動き</p>\n<p><span data-source-marker=\"dashed-arrow\" data-source-color=\"green\" style=\"color:#315837\">⇢</span> 共産党の動き</p>\n<p><span data-source-marker=\"arrow\" data-source-color=\"pink\" style=\"color:#f0a0a0\">➡</span> 日本の動き</p>",
  "321": "<h2>321</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">日本の侵略と国共内戦</u></p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">共産党は<ruby>長征<rt>ちょうせい</rt></ruby>を開始。そして……<ruby>西安<rt>せいあん</rt></ruby>事件が起きた！</strong></span></h4>\n<p>日本の華北での勢力拡大に対して蔣介石は「日本の<ruby>侵略<rt>しんりゃく</rt></ruby>は皮膚病、共産党は内臓病みたいなもんだ。内臓病は悪くなると手遅れになる。<strong class=\"source-bold\">国内統一が先、日本と戦うのはそのあと</strong>だ！」と主張して、共産党への攻撃を強めていた。これに対して共産党は、「<strong class=\"source-bold\">日本と戦わなければならない</strong>。そのためには<strong class=\"source-bold\">蔣介石を打倒</strong>する！」と言ってた。つまり、どっちも相手を<ruby>潰<rt>つぶ</rt></ruby>すって言ってる……。そして、<ruby>塘沽<rt>タンクー</rt></ruby>停戦協定で華北の問題に区切りをつけた蔣介石の猛攻撃で<strong class=\"source-bold\">共産党軍（<ruby>紅軍<rt>こうぐん</rt></ruby>）は大敗北</strong>した。根拠地を維持できなくなった共産党は<strong class=\"source-bold\"><ruby>瑞金<rt>ずいきん</rt></ruby>から撤退</strong>することを決め、蔣介石の攻撃から逃げるために、西へと移動を始めたんだ。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">長征</strong></span>の始まりだよ。</p>\n<p>ただ、長征の目的は1935年の<strong class=\"source-bold\"><ruby>遵義<rt>じゅんぎ</rt></ruby>会議</strong>をきっかけに変わっていくよ。この会議で、共産党はこれまでの運動が失敗した原因を話し合った。結局残ったのは、<ruby>毛沢東<rt>もうたくとう</rt></ruby>の「農村路線」のほうだったからね。こうして、<ruby>周恩来<rt>しゅうおんらい</rt></ruby>の協力で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">毛沢東</strong></span>が<strong class=\"source-bold\">軍の指揮権を握り</strong>、逆に共産党内の<strong class=\"source-bold\">モスクワ留学派の力が弱まった</strong>んだ。そして、毛沢東が「北上して華北に根拠地をつくり、日本と戦うべきである」と主張したから、<strong class=\"source-bold\">紅軍は北上を始めた</strong>よ。</p>\n<blockquote><p>大雪山を越えて、大湿原を渡って……この長征を通じて毛沢東が権力を確立したんだよ</p></blockquote>\n<p>そして、長征の途中でもう一つ大きな動きがあったよ。モスクワで開かれていた<strong class=\"source-bold\">コミンテルン第7回大会</strong>で反ファシズムのための統一戦線をつくる「<strong class=\"source-bold\">人民戦線</strong>」戦術が採用されると、モスクワを訪問していた<strong class=\"source-bold\">中国共産党の代表団</strong>が、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>八<rt>はち</rt></ruby>・<ruby>一<rt>いち</rt></ruby>宣言</strong></span>を発表したんだ。これは国民党を含む幅広い勢力に、<strong class=\"source-bold\">内戦を停止</strong>して日本と戦うために協力すること（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>抗日<rt>こうにち</rt></ruby>民族統一戦線</strong></span>の結成）を呼びかけ、それをジャマする<strong class=\"source-bold\">蔣介石の打倒</strong>を訴えた。このあと、中国では「一致抗日」の声が日に日に高まったんだ。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">合</strong></span><span data-source-color=\"white\" data-source-background=\"brown\" style=\"color:#ffffff;background-color:#a43725\"><strong class=\"source-bold\">否</strong></span><strong class=\"source-bold\">の分かれ目</strong>　<span data-source-border=\"brown\" data-source-border-style=\"dotted\" style=\"border:1px dotted #a43725\"><strong class=\"source-bold\">2度の国共合作の違い</strong></span></h3>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1次国共合作</strong></span> ［1924］ ……<strong class=\"source-bold\">中国国民党一全大会</strong>で成立</p>\n<blockquote><p><span data-source-color=\"green\" style=\"color:#315837\">▶</span>「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>連<rt>れん</rt></ruby>ソ</strong></span>・<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>容共<rt>ようきょう</rt></ruby></strong></span>・<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>扶助工農<rt>ふじょこうのう</rt></ruby></strong></span>」の新政策に基づく</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span>共産党員が<strong class=\"source-bold\">個人の資格</strong>で<strong class=\"source-bold\">共産党籍のまま国民党に入党</strong>（国民党が共産党を吸収）</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span>目標は<strong class=\"source-bold\">北京政府打倒</strong>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>北伐<rt>ほくばつ</rt></ruby></strong></span>） <span data-source-color=\"green\" style=\"color:#315837\">➡</span><strong class=\"source-bold\"><ruby>黄埔<rt>こうほ</rt></ruby>軍官学校</strong>を設立（校長は<strong class=\"source-bold\">蔣介石</strong>）</p></blockquote>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第2次国共合作</strong></span> ［1937］ ……日中戦争<ruby>勃発<rt>ぼっぱつ</rt></ruby>後に成立</p>\n<blockquote><p><span data-source-color=\"green\" style=\"color:#315837\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">西安事件</strong></span>をきっかけに、蔣介石が<strong class=\"source-bold\">内戦停止</strong>に合意</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span><strong class=\"source-bold\">国民党と共産党は対等</strong>だが、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">紅軍</strong></span>は<strong class=\"source-bold\">蔣介石の指揮下</strong>に入る（<strong class=\"source-bold\"><ruby>八路軍<rt>はちろぐん</rt></ruby></strong>）</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span>目標は<strong class=\"source-bold\">日本の打倒</strong>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">抗日民族統一戦線</strong></span>）</p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "322": "<h2>322</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第17回</strong></span> 戦間期の東アジア</p>\n<p>そして、<strong class=\"source-bold\"><ruby>八<rt>はち</rt></ruby>・<ruby>一<rt>いち</rt></ruby>宣言に共感</strong>したのが、自分の本拠地を日本に奪われた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>張学良<rt>ちょうがくりょう</rt></ruby></strong></span>だ。張学良は日本から<ruby>満洲<rt>まんしゅう</rt></ruby>を取り返したいから、共産党と内戦なんかをやってる場合じゃない。最初は「<strong class=\"source-bold\">内戦をやめて、共産党と<ruby>抗日<rt>こうにち</rt></ruby>で協力しよう</strong>」と<ruby>蔣介石<rt>しょうかいせき</rt></ruby>を説得したんだけど、蔣介石は全く聞く耳を持たなかったから、張学良は共産党の<ruby>周恩来<rt>しゅうおんらい</rt></ruby>とも会談をして、ついに<strong class=\"source-bold\">蔣介石を武力によって説得</strong>することを決意したんだ。</p>\n<p>1936年12月、<strong class=\"source-bold\"><ruby>西安<rt>せいあん</rt></ruby></strong>で内戦停止を求める学生たちのデモが起きた。蔣介石はこれを武力で<ruby>鎮圧<rt>ちんあつ</rt></ruby>しようとしていたから、張学良は「蔣介石は私が説得するから、デモをやめろ！」と学生たちを説得すると、ついに東北軍を率いて立ち上がり、保養地の<ruby>華清池<rt>かせいち</rt></ruby>にいた<strong class=\"source-bold\">蔣介石を監禁</strong>したんだ！。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">西安事件</strong></span>だよ。<strong class=\"source-bold\">張学良は内戦停止を要求</strong>したんだけど、蔣介石は断固拒否した。その後、<strong class=\"source-bold\">共産党の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">周恩来</strong></span></strong>も説得に加わり、ついに<strong class=\"source-bold\">蔣介石は内戦の停止に合意</strong>したんだ。周恩来は、<ruby>黄埔<rt>こうほ</rt></ruby>軍官学校の時には蔣介石の部下だったから、<ruby>因縁<rt>いんねん</rt></ruby>の再会だね。この時の合意が、日中戦争勃発後に第2次国共合作ができた背景だよ。</p>\n<h3>＋<span data-source-color=\"red\" style=\"color:#e52715\">α</span><u data-source-underline-color=\"black\" style=\"text-decoration-color:#222222\"><strong class=\"source-bold\">ちょっと寄り耳</strong></u><span data-source-marker=\"curved-arrow\" data-source-color=\"black\" style=\"color:#222222\">⤴</span></h3>\n<blockquote><p>中国近現代史に大きな影響を与えたのが<ruby>宋家<rt>そうけ</rt></ruby>の三姉妹だよ。</p>\n<p><ruby>辛亥<rt>しんがい</rt></ruby>革命ののち、<ruby>孫文<rt>そんぶん</rt></ruby>が日本に逃げていた時、彼を支援したのが実業家の<ruby>宋嘉樹<rt>そうかじゅ</rt></ruby>と日本人の<ruby>梅屋庄吉<rt>うめやしょうきち</rt></ruby>。そして梅屋氏の仲介で宋嘉樹の次女<ruby>宋慶齢<rt>そうけいれい</rt></ruby>は孫文の妻となり、孫文の死後、蔣介石が三女の<ruby>宋美齢<rt>そうびれい</rt></ruby>と結婚したから、蔣介石は孫文の義理の弟になった。そして、長女の<ruby>宋靄齢<rt>そうあいれい</rt></ruby>は、大実業家で国民政府の要職に<ruby>就<rt>つ</rt></ruby>く<ruby>孔祥熙<rt>こうしょうき</rt></ruby>の妻で、宋美齢の兄が国民政府の財政部長となる<ruby>宋子文<rt>そうしぶん</rt></ruby>だ。</p>\n<p>西安事件のウラで、この宋家の人脈が動いたよ。宋慶齢は、「ソ連と連携せよ」との孫文の遺言を守って密かに共産党に入党したけど、一族の連帯意識から宋子文や宋美齢（蔣介石の妻）ともつながりを保っていた。西安事件の時、蔣介石と共産党の間を取り持ったのは宋子文だし、周恩来とともに蔣介石を説得したのは、妻の宋美齢だよ。</p>\n<p>戦後、宋慶齢は中華人民共和国の要職に<ruby>就<rt>つ</rt></ruby>き、宋美齢は蔣介石を支えて外交などで活躍するなど、まさに中国近現代史を動かした姉妹なんだ。「宋家の三姉妹」っていう映画にもなっているから、興味があったら観てみてね。</p></blockquote>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">4</span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">日中戦争</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\"><ruby>盧溝橋<rt>ろこうきょう</rt></ruby>事件をきっかけに、日中戦争勃発！</strong></span></h4>\n<p>1937年7月、北京郊外で起きた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">盧溝橋事件</strong></span>は、その後の中国情勢を大きく変えることになった。これは<strong class=\"source-bold\">日本の<ruby>北京駐屯軍<rt>ペキンちゅうとんぐん</rt></ruby></strong>（1901年の北京議定書からずっと駐兵していた日本軍）<strong class=\"source-bold\">と中国軍の小さな軍事衝突</strong>だったんだけど、すでに<strong class=\"source-bold\">西安事件で内戦を停止</strong>していた蔣介石は軍の総動員を命令して徹底抗戦を宣言した。さらに、翌</p>",
  "323": "<h2>323</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">日中戦争</u></p>\n<p>月には<ruby>上海<rt>シャンハイ</rt></ruby>でも武力衝突（<strong class=\"source-bold\">第2次上海事変</strong>）が起こり、<strong class=\"source-bold\">全面戦争に突入</strong>！　ここからが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日中戦争</strong></span>だ。そして、9月には<strong class=\"source-bold\">共産党の<ruby>紅軍<rt>こうぐん</rt></ruby></strong>が国民革命軍の<strong class=\"source-bold\"><ruby>八路軍<rt>はちろぐん</rt></ruby></strong>として<strong class=\"source-bold\">蔣介石の指揮下に入り</strong>、正式に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第2次国共合作</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">抗日民族統一戦線</strong></span>】</strong>が成立したんだ。</p>\n<p>それはそうと、この戦闘で<strong class=\"source-bold\">日本も中国も<ruby>宣戦布告<rt>せんせんふこく</rt></ruby>をしていない</strong>。じゃあ、なんで両国とも宣戦布告をしなかったんだろう？　それは、<strong class=\"source-bold\">アメリカの中立法</strong>の問題だよ。<strong class=\"source-bold\">中立法</strong>っていうのは、「戦争」をしている国への軍需品の輸出や金融面での取引を禁止する法律だから、日本は「戦争」じゃなくて、たまたまちょっとだけ起きた「<ruby>事変<rt>じへん</rt></ruby>」ってことにしたんだ（だから日本は「<ruby>支那事変<rt>しなじへん</rt></ruby>」って呼んだよ）。</p>\n<p>でも、どんな名前で呼んだところで、満洲事変から始まった武力衝突は、<strong class=\"source-bold\">日中間の全面戦争にまで発展</strong>したってことだ。<strong class=\"source-bold\">日本軍</strong>は「<strong class=\"source-bold\"><ruby>南京<rt>ナンキン</rt></ruby>さえ落とせば、中国は降伏する</strong>」と思ってたから、まず上海に総攻撃をかけて陥落させ、続いて国民政府のある南京に迫ったんだ。これに対し、<strong class=\"source-bold\">蔣介石</strong>は戦争が<strong class=\"source-bold\">長期戦になると判断</strong>して、兵力を温存するために、国民政府の首都をいったん<strong class=\"source-bold\"><ruby>武漢<rt>ぶかん</rt></ruby></strong>、さらに内陸の<strong class=\"source-bold\"><ruby>四川<rt>しせん</rt></ruby>省</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>重慶<rt>じゅうけい</rt></ruby></strong></span>に移すことを決めたんだけど、この時、中国軍は南京からの撤退に失敗して多数の犠牲者を出した。そして12月には、<strong class=\"source-bold\">日本が南京を陥落させた</strong>んだけど、「これで中国は降伏する」という甘い読みから、占領部隊が多数の<ruby>捕虜<rt>ほりょ</rt></ruby>や市民を殺害する<strong class=\"source-bold\">南京事件</strong>を引き起こして、国際的に非難された。一方、中国側は<strong class=\"source-bold\">重慶に逃げれば</strong>、<ruby>雲南<rt>うんなん</rt></ruby>を経由して<strong class=\"source-bold\">インドシナ（フランス領）やビルマ（イギリス領）から支援を受けられる</strong>から、長期戦に持ち込んでイギリスやアメリカの支援に期待することにしたんだ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">鉄道と都市だけの<ruby>占領<rt>せんりょう</rt></ruby>で戦線が<ruby>膠着<rt>こうちゃく</rt></ruby>。ついにソ連とも軍事衝突した！</strong></span></h4>\n<p>ただ、日本は<ruby>華北<rt>かほく</rt></ruby>から<ruby>江南<rt>こうなん</rt></ruby>へと、<strong class=\"source-bold\">鉄道に沿って都市を占領</strong>するだけだった。ていうか、あれだけ広い<strong class=\"source-bold\">中国の農村部まで占領するのはムリ</strong>だよ。中国では共産党が農村部に根拠地（<strong class=\"source-bold\">解放区</strong>）をつくって<strong class=\"source-bold\">ゲリラ戦</strong>で対抗し、日本軍はあっという間に行き詰った。このため、日本では<ruby>近衛<rt>このえ</rt></ruby>内閣が国内のすべてのヒトやモノを戦争に動員するために<strong class=\"source-bold\">国家総動員法</strong>をつくり、さらに戦争の正当化のために<strong class=\"source-bold\">日本・満洲・中華民国が3国で提携</strong>してアメリカやイギリスに対抗するっていう<strong class=\"source-bold\"><ruby>東亜新秩序<rt>とうあしんちつじょ</rt></ruby></strong>を目標に掲げた。これは中国各地につくった<ruby>傀儡<rt>かいらい</rt></ruby>政権に向けたものだけど、だいたい戦争やってる最中に連携を持ち掛けたって、うまくいくわけがないよ。</p>\n<p>こののち、戦線が膠着して身動きが取れなくなった日本は、<strong class=\"source-bold\">重慶に爆撃</strong>をしたり、国民党指導者の一人で<strong class=\"source-bold\">蔣介石のライバル</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>汪兆銘<rt>おうちょうめい</rt></ruby></strong></span>を抱きこんで、傀儡政権である「<strong class=\"source-bold\">南京国民政府</strong>」をつくったりと、さまざまな手を打ったけどどれもうまくいかず、逆に戦線を拡大したために米英に警戒されて、ますます<strong class=\"source-bold\">国際的に孤立</strong>したんだよ。</p>\n<p>そして同じころ、日中戦争中の<strong class=\"source-bold\">ソ連の動きを警戒していた日本</strong>は、「満洲にソ連軍が攻め込んできたら、中国との戦争を続けることが不可能になる」と考えて、モンゴルと「満洲国」の国境地帯で<strong class=\"source-bold\">ソ連軍と武力衝突</strong>を起こしたんだ。でも1939年の<strong class=\"source-bold\">ノモンハン事件</strong>では、ソ連の戦車軍団にボコボコに負けちゃった。しかも、同盟</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "324": "<h2>324</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第17回</strong></span> 戦間期の東アジア</p>\n<p>国のドイツが<strong class=\"source-bold\">独ソ<ruby>不可侵<rt>ふかしん</rt></ruby>条約</strong>を結んじゃったから、もはやソ連と戦っている場合じゃない。<strong class=\"source-bold\">日本はソ連と停戦</strong>すると、東南アジアに向かう<strong class=\"source-bold\">南進政策</strong>を考え始めたんだけど、そんなことしたらますます敵が増えちゃうよ。</p>\n<h3><strong class=\"source-bold\">〈日中戦争〉</strong></h3>\n<blockquote><p>中国からソ連、さらに南進政策へ……敵ばかりが増えて、もはや泥沼だ</p></blockquote>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><strong class=\"source-bold\">ソ連</strong></td><td></td></tr><tr><td><strong class=\"source-bold\">モンゴル人民共和国</strong></td><td></td></tr><tr><td><span data-source-marker=\"area\" data-source-color=\"pink\" data-source-pattern=\"vertical-lines\" style=\"color:#f0a0a0\">▥</span>「<strong class=\"source-bold\">満洲国</strong>」</td><td></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">ノモンハン事件［1939.5〜.9］</span></td><td><span data-source-marker=\"cross\" data-source-color=\"red\" style=\"color:#e52715\">×</span></td></tr><tr><td><span data-source-marker=\"point\" data-source-color=\"black\" style=\"color:#222222\">○</span> 北京</td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">盧溝橋事件<br>［1937.7］</span> <span data-source-marker=\"cross\" data-source-color=\"red\" style=\"color:#e52715\">×</span></td></tr><tr><td><span data-source-marker=\"point\" data-source-color=\"red\" style=\"color:#e52715\">●</span> 延安<br>（共産党）</td><td><span data-source-color=\"brown\" style=\"color:#a43725\">➡</span></td></tr><tr><td><span data-source-marker=\"point\" data-source-color=\"black\" style=\"color:#222222\">○</span> 西安</td><td></td></tr><tr><td><span data-source-marker=\"point\" data-source-color=\"brown\" style=\"color:#a43725\">●</span> 南京</td><td></td></tr><tr><td><span data-source-border=\"pink\" style=\"border:1px solid #f0a0a0\">第2次上海事変［1937.8］</span></td><td><span data-source-marker=\"cross\" data-source-color=\"red\" style=\"color:#e52715\">×</span></td></tr><tr><td><span data-source-marker=\"point\" data-source-color=\"brown\" style=\"color:#a43725\">●</span> 武漢</td><td></td></tr><tr><td><span data-source-marker=\"point\" data-source-color=\"brown\" style=\"color:#a43725\">●</span> 重慶</td><td><span data-source-border=\"brown\" style=\"border:1px solid #a43725\">国民政府の移動</span> <span data-source-marker=\"dashed-arrow\" data-source-color=\"brown\" style=\"color:#a43725\">⇢</span></td></tr><tr><td><span data-source-border=\"black\" style=\"border:1px solid #222222\">援蔣ルート</span></td><td><span data-source-marker=\"dashed-arrow\" data-source-color=\"red\" style=\"color:#e52715\">⇢</span></td></tr><tr><td><span data-source-marker=\"point\" data-source-color=\"black\" style=\"color:#222222\">○</span> 広州</td><td></td></tr><tr><td><strong class=\"source-bold\">英領<br>ビルマ</strong></td><td></td></tr><tr><td><span data-source-marker=\"point\" data-source-color=\"black\" style=\"color:#222222\">○</span> <em data-source-italic=\"true\" style=\"font-style:italic\">ハノイ</em></td><td></td></tr><tr><td><strong class=\"source-bold\">仏領</strong></td><td></td></tr><tr><td><strong class=\"source-bold\">タイ</strong></td><td></td></tr><tr><td><strong class=\"source-bold\">インドシナ</strong></td><td></td></tr><tr><td><span data-source-border=\"pink\" style=\"border:1px solid #f0a0a0\">北部仏印進駐<br>［1940.9］</span></td><td></td></tr></tbody></table></div>\n<p><span data-source-marker=\"arrow\" data-source-color=\"pink\" style=\"color:#f0a0a0\">➡</span> 日本軍の侵攻</p>\n<p><span data-source-color=\"brown\" style=\"color:#a43725\">➡</span> 中国軍の攻撃（共産党も含む）</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">南進政策でアメリカとの対立が深刻になり、ついに日米が開戦！</strong></span></h4>\n<p>日本がどんどん戦線を拡大するのを見て、ついに<strong class=\"source-bold\">アメリカ</strong>が動き出したよ。さっきも話したけど、アメリカには<strong class=\"source-bold\">交戦国に戦略物資を輸出しちゃいけない</strong>っていう<strong class=\"source-bold\">中立法</strong>がある。アメリカは日本に対して「日本は交戦国だから、戦略物資は輸出してやらない」と言って<strong class=\"source-bold\">日米通商航海条約を<ruby>破棄<rt>はき</rt></ruby></strong>し、<strong class=\"source-bold\">石油・くず鉄の輸出制限</strong>を決めたんだ。当時、石油の多くをアメリカからの輸入に頼っていた日本は、「石油がなくなったら、戦争を続けるのは不可能だ」と焦り、石油を確保するために<strong class=\"source-bold\">東南アジアに進出</strong>する<strong class=\"source-bold\">南進政策</strong>を計画し始めたんだ。当時すでに<strong class=\"source-bold\">インドネシア（オランダ領だよね）で石油が採れた</strong>からね。</p>\n<p>そして、<strong class=\"source-bold\">ドイツ軍のポーランド</strong><ruby>侵攻<rt>しんこう</rt></ruby>によって<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第二次世界大戦</strong></span>が<ruby>勃発<rt>ぼっぱつ</rt></ruby>し、1940年に入ると、ヨーロッパでは<strong class=\"source-bold\">ドイツ</strong>があっという間に<strong class=\"source-bold\">ベルギー、オランダ</strong>、さらには<strong class=\"source-bold\">フランスを降伏させた</strong>。この時日本では「バスに乗り遅れるな！」って主張があっ</p>",
  "325": "<h2>325</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">日中戦争</u></p>\n<p>た。これは、ドイツが戦争に勝つ「バス」に乗ってるから、乗り遅れずに、一気に東南アジアを取れ！ってことだ。だって、<strong class=\"source-bold\">インドシナ（ベトナム）はフランス領、インドネシアはオランダ領</strong>だから、どっちも<strong class=\"source-bold\">本国がドイツに降伏</strong>してるでしょ。今なら一気に勝てる！　こうして日本は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フランス領インドシナ北部</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">北部仏印</strong></span>】</strong>に軍を進めたよ。これには、<strong class=\"source-bold\">南進政策の拠点</strong>をつくること、さらに<ruby>重慶<rt>じゅうけい</rt></ruby>の<ruby>蔣介石<rt>しょうかいせき</rt></ruby>に支援物資を送る「<strong class=\"source-bold\"><ruby>援蔣<rt>えんしょう</rt></ruby>ルート</strong>」<strong class=\"source-bold\">を<ruby>遮断<rt>しゃだん</rt></ruby></strong>すること、っていう2つの目的があるよ。そして<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日独伊三国同盟</strong></span>を結んだから、ドイツと戦っている<strong class=\"source-bold\">イギリスとも対立</strong>したんだ。</p>\n<p>こうなると、東南アジアに利権を持つ<strong class=\"source-bold\">アメリカ、イギリス、オランダ</strong>との対決は避けられない。日本ではこれらの国を「<strong class=\"source-bold\">ABCD包囲陣</strong>」（AはAmerica《アメリカ》、BはBritain《イギリス》、CはChina《中国》、DはDutch《オランダ》）と呼んだ。そして、南進政策の最後の準備として、北からソ連軍が攻めてこないように<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日ソ中立条約</strong></span>を結んだから、もはや<strong class=\"source-bold\">日本の東南アジア進出は止まらない</strong>ね。</p>\n<p>1941年、アメリカとの戦争を回避しようとした<ruby>近衛<rt>このえ</rt></ruby>内閣が、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日米交渉</strong></span>を始めたよ。でも、交渉中に日本軍が<strong class=\"source-bold\">フランス領インドシナ南部</strong>に進駐したから、アメリカの態度が強硬になり、日本への石油輸出を禁止した！。日本でも軍部が交渉打ち切りを主張したから近衛内閣は倒れ、<strong class=\"source-bold\">陸軍出身</strong>の<strong class=\"source-bold\"><ruby>東条英機<rt>とうじょうひでき</rt></ruby></strong>が首相になった。そしてアメリカが、日本の<strong class=\"source-bold\">中国からの完全<ruby>撤兵<rt>てっぺい</rt></ruby>と三国同盟脱退</strong>を要求（「<strong class=\"source-bold\">ハル＝ノート</strong>」）すると交渉は決裂。1941年12月には日本がアメリカ海軍の基地だったハワイの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>真珠湾<rt>しんじゅわん</rt></ruby>を奇襲</strong></span>して<strong class=\"source-bold\">日米が開戦</strong>したんだ。この戦争をアメリカでは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">太平洋戦争</strong></span>、日本では<strong class=\"source-bold\"><ruby>大東亜<rt>だいとうあ</rt></ruby>戦争</strong>と呼んだよ。今では、太平洋から東南アジアも含む地域で戦われたから、<strong class=\"source-bold\">アジア・太平洋戦争</strong>って呼び方も使われるね。この続きは、第二次世界大戦のところで話すからね。</p>\n<p>じゃあ、戦間期の東アジアはこれでおしまい。最後に年号check！</p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">!!</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">年号</strong></span><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">のツボ</strong></span></h3>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">第1次国共合作の成立</strong> ［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1924</strong></span>］ （<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>遠<rt>1</rt></ruby><ruby>く<rt>9</rt></ruby><ruby>虹<rt>24</rt></ruby></strong></span>見る　国共合作）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\"><ruby>北伐<rt>ほくばつ</rt></ruby>の開始</strong> ［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1926</strong></span>］ （北伐に　<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>と<rt>1</rt></ruby>っ<ruby>く<rt>9</rt></ruby><ruby>に<rt>2</rt></ruby><ruby>向<rt>6</rt></ruby></strong></span>かった）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\"><ruby>上海<rt>シャンハイ</rt></ruby>クーデタ</strong> ［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1927</strong></span>］ （共産党　<ruby>弾圧<rt>だんあつ</rt></ruby>避けて　<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>卑<rt>1</rt><rt data-source-position=\"below\" style=\"ruby-position:under\">ヒ</rt></ruby><ruby>屈<rt>92</rt><rt data-source-position=\"below\" style=\"ruby-position:under\">クツ</rt></ruby><ruby>な<rt>7</rt></ruby></strong></span>逃亡）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\"><ruby>満洲<rt>まんしゅう</rt></ruby><ruby>事変<rt>じへん</rt></ruby>の勃発</strong> ［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1931</strong></span>］ （<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>戦<rt>19</rt></ruby><ruby>さ<rt>3</rt></ruby><ruby>今<rt>1</rt></ruby></strong></span>から　満洲事変）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\"><ruby>長征<rt>ちょうせい</rt></ruby>の開始</strong> ［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1934</strong></span>］ （<ruby>瑞金<rt>ずいきん</rt></ruby>に　<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>遠<rt>1</rt></ruby><ruby>く<rt>9</rt></ruby><ruby>さ<rt>3</rt></ruby><ruby>よ<rt>4</rt></ruby></strong></span>うなら）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\"><ruby>八<rt>はち</rt></ruby>・<ruby>一<rt>いち</rt></ruby>宣言</strong> ［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1935</strong></span>］ （<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>戦<rt>19</rt></ruby><ruby>さ<rt>3</rt></ruby></strong></span>は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>ゴ<rt>5</rt></ruby></strong></span>メンだ　内戦停止）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\"><ruby>盧溝橋<rt>ろこうきょう</rt></ruby>事件</strong> ［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1937</strong></span>］ （<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>戦<rt>19</rt></ruby><ruby>さ<rt>3</rt></ruby><ruby>長<rt>7</rt></ruby></strong></span>びく　日中戦争）</p>\n<p>次回は<strong class=\"source-bold\">世界<ruby>恐慌<rt>きょうこう</rt></ruby></strong>とその後の欧米諸国だよ。ヨーロッパでも戦争のにおいがプンプンし始める。近現代史もいよいよ大詰めだよ！　<ruby>頑張<rt>がんば</rt></ruby>っていこう〜。</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>"
};

